	public int CameraAltitude
	{
		get
		{
			if (WorldWindow1?.DrawArgs?.WorldCamera == null)
			{
				return 0;
			}
			return (int)Math.Round(WorldWindow1.DrawArgs.WorldCamera.Altitude);
		}
		set
		{
			if (WorldWindow1?.DrawArgs?.WorldCamera == null || (float)value == WorldWindow1.DrawArgs.WorldCamera.Altitude)
			{
				return;
			}
			try
			{
				expressionConnection = true;
				if (value == 0)
				{
					value = 1700000;
				}
				WorldWindow1.DrawArgs.WorldCamera.Altitude = value;
				if (!Information.IsNothing(Client.CurrentSide))
				{
					Client.CurrentSide.CameraAlt = value;
				}
				MapRender_Geo();
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception exception_ = ex;
				exception_?.Data.Add("Error at 20012300001", exception_.Message);
				GameGeneral.WriteExceptionsToLog(ref exception_);
				if (Debugger.IsAttached)
				{
					Debugger.Break();
				}
				ProjectData.ClearProjectError();
			}
			finally
			{
				expressionConnection = false;
			}
		}
	}

