	private void CheckAccount()
	{
		if (CommandLayer.IsAlaCarteDisabled("CL_DrawChaffClouds") || Client.CurrentScenario.ChaffClouds.Count == 0)
		{
			return;
		}
		try
		{
			System.Drawing.Pen pen = new System.Drawing.Pen(System.Drawing.Color.DarkCyan, 2f);
