			for (int i = Client.CurrentScenario.ChaffClouds.Count - 1; i >= 0; i += -1)
			{
				ChaffCorridorCloud chaffCorridorCloud = Client.CurrentScenario.ChaffClouds[i];
				int num = GameGeneral.LockRandom_0.Next(100, 1000);
				Geopoint_Struct[] rectangularArea = Math2.GetRectangularArea(chaffCorridorCloud.GetLatitude(), chaffCorridorCloud.GetLongitude(), chaffCorridorCloud.CoverageLength, chaffCorridorCloud.CoverageWidth, chaffCorridorCloud.CurrentHeading);
				double num2 = rectangularArea.Select((Geopoint_Struct GP) => GP.Latitude).Max();
				double num3 = rectangularArea.Select((Geopoint_Struct GP) => GP.Latitude).Min();
				double num4 = rectangularArea.Select((Geopoint_Struct GP) => GP.Longitude).Max();
				double num5 = rectangularArea.Select((Geopoint_Struct GP) => GP.Longitude).Min();
				LockRandom lockRandom_ = GameGeneral.LockRandom_0;
				int num6 = num;
				System.Drawing.Point point;
				for (int j = 1; j <= num6; j++)
				{
					try
					{
						double double_ = Math2.ReflectClass(num3 + lockRandom_.NextDouble() * (num2 - num3));
						double double_2 = Math2.VisitClass(num5 + lockRandom_.NextDouble() * (num4 - num5));
						if (ManagerListenerManager.CreateInterruptibleMap(WorldWindow1, double_, double_2) && GeoPoint.IsInsideThisArea(double_, double_2, rectangularArea))
						{
							point = ManagerListenerManager.SetInterruptibleMap(WorldWindow1, double_, double_2);
							issuerConnection.DrawLine(pen.Color, 2f, new System.Drawing.Point(point.X - 1, point.Y), new System.Drawing.Point(point.X + 1, point.Y));
						}
						string_ = (SimConfiguration.DefaultGamePreferences.ShowAltitudeInFeet ? (Conversions.ToString((int)Math.Round((float)chaffCorridorCloud.CurtainFloor * 3.28084f / 1000f)) + "-" + Conversions.ToString((int)Math.Round((float)chaffCorridorCloud.CurtainCeiling * 3.28084f / 1000f)) + "Kft") : (Conversions.ToString((int)Math.Round((double)chaffCorridorCloud.CurtainFloor / 1000.0)) + "-" + Conversions.ToString((int)Math.Round((double)chaffCorridorCloud.CurtainCeiling / 1000.0)) + "KM"));
					}
					catch (Exception ex)
					{
						ProjectData.SetProjectError(ex);
						Exception exception_ = ex;
						exception_?.Data.Add("Error at 200158", exception_.Message);
						GameGeneral.WriteExceptionsToLog(ref exception_);
						if (Debugger.IsAttached)
						{
							Debugger.Break();
						}
						ProjectData.ClearProjectError();
					}
				}
				point = ManagerListenerManager.SetInterruptibleMap(WorldWindow1, chaffCorridorCloud.GetLatitude(), chaffCorridorCloud.GetLongitude());
				issuerConnection.DrawText(pen.Color, point.X, point.Y, string_, 0.0, 15, ExWorldWind.FontWeight.Bold, bool_0: false, bool_1: false, "微软雅黑");
			}
		}
		catch (Exception projectError)
