	private void ConcatAccount()
	{
		if (CommandLayer.IsAlaCarteDisabled("CL_DrawMissionAreas"))
		{
			return;
		}
		switch (SimConfiguration.DefaultGamePreferences.ShowMissionArea)
		{
		case Game.GamePreferences.ObjectVisibilitySetting.All:
			if (Client.CurrentSide == null)
			{
				break;
			}
			{
				foreach (Mission item in Client.CurrentSide.GetMissionsTotal(Client.CurrentScenario))
				{
					InterruptAccount(item);
				}
				break;
			}
		case Game.GamePreferences.ObjectVisibilitySetting.Selected:
			if (Client.MissionEditorWindow != null && Client.CurrentSide != null && Client.MissionEditorWindow.SelectedMission != null && Client.CurrentSide.GetMissionsTotal(Client.CurrentScenario).Contains(Client.MissionEditorWindow.SelectedMission))
			{
				InterruptAccount(Client.MissionEditorWindow.SelectedMission);
			}
			break;
		case Game.GamePreferences.ObjectVisibilitySetting.DontShow:
			break;
		}
	}

