	private void PopAccount()
	{
		if (CommandLayer.IsAlaCarteDisabled("CL_DrawPlottedCourses") || (SimConfiguration.DefaultGamePreferences.ShowPlottedPaths == Game.GamePreferences.PlottedPathsVisibilitySetting.DontShow && Client.CurrentUserAction != Client.UserAction.PlottingCourse))
		{
			return;
		}
		int int_ = 255;
		float float_ = 1f;
		if (Client.SelectedUnit != null && Client.SelectedUnit.IsActiveUnit && !((ActiveUnit)Client.SelectedUnit).IsDestroyed)
		{
			ActiveUnit activeUnit = (ActiveUnit)Client.SelectedUnit;
			if (activeUnit.Navigator.HasPlottedCourse() && (SimConfiguration.DefaultGamePreferences.ShowPlottedPaths != Game.GamePreferences.PlottedPathsVisibilitySetting.DontShow || Client.CurrentUserAction == Client.UserAction.PlottingCourse))
			{
				CL_DrawPlottedCourse(activeUnit);
			}
			if (activeUnit.Navigator.HasFlightPlan)
			{
				if (activeUnit.IsGroup)
				{
					activeUnit = ((Group)activeUnit).GroupLead;
				}
				if (activeUnit.IsAircraft && SimConfiguration.DefaultGamePreferences.ShowFlightPlans_Airborne != Game.GamePreferences.FlightPlansVisibilitySetting_Airborne.DontShow)
				{
					CL_DrawFlightPlan(activeUnit.Navigator.GetFlight(), System.Drawing.Color.FromArgb(255, System.Drawing.Color.White), ref recordConnection, ref m_PredicateConnection, System.Drawing.Drawing2D.DashStyle.DashDotDot, System.Drawing.Drawing2D.DashStyle.Dot, null);
				}
			}
		}
		if (SimConfiguration.DefaultGamePreferences.ShowPlottedPaths != 0)
		{
			return;
		}
		try
		{
			if (Client.MapVisibleUnits.Count <= 0)
			{
				return;
			}
			for (int i = Client.MapVisibleUnits.Count - 1; i >= 0; i += -1)
			{
				Module_Unit.Unit unit = Client.MapVisibleUnits[i];
				if (!unit.IsActiveUnit)
				{
					continue;
				}
				ActiveUnit activeUnit2 = (ActiveUnit)unit;
				if (Client.CanSeeAllPrivateInformationOnThisUnit(activeUnit2) && activeUnit2.Navigator.HasPlottedCourse())
				{
					Client.AdjustTransparency(ref float_, ref int_, activeUnit2);
					if (activeUnit2.GetUnitSide() != null && (activeUnit2.GetUnitSide() == Client.CurrentSide || (Client.CurrentSide.GetConsidersThisSideToBe(activeUnit2.GetUnitSide()) == Misc.PostureStance.Friendly && ManagerListenerManager.CompareInterruptibleMap(WorldWindow1, activeUnit2))) && (object)activeUnit2.GetType() != typeof(UnguidedRocket) && (!activeUnit2.IsGroupLead() || Client.CurrentMapProfile.ViewMode != 0))
					{
						CL_DrawPlottedCourse(activeUnit2);
					}
				}
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

