	private void InstantiateAccount()
	{
		if (CommandLayer.IsAlaCarteDisabled("CL_DrawFlightPlans_Planned") || SimConfiguration.DefaultGamePreferences.ShowFlightPlans_Planned == Game.GamePreferences.FlightPlansVisibilitySetting_Planned.DontShow || (!Client.AirTaskingOrderWindow.Visible && !Client.FlightPlanEditorWindow.Visible))
		{
			return;
		}
		try
		{
			for (int i = Client.CurrentSide.Missions.Count - 1; i >= 0; i += -1)
			{
				try
				{
					Mission mission = Client.CurrentSide.Missions[i];
					if (!mission.TestValue() || (SimConfiguration.DefaultGamePreferences.ShowFlightPlans_Planned == Game.GamePreferences.FlightPlansVisibilitySetting_Planned.SelectedTaskPool && (mission.Category == Mission.MissionCategory.TaskPool || mission.Category == Mission.MissionCategory.Mission) && Client.AirTaskingOrderWindow.Visible && Client.AirTaskingOrderWindow.SelectedMission != mission) || (SimConfiguration.DefaultGamePreferences.ShowFlightPlans_Planned == Game.GamePreferences.FlightPlansVisibilitySetting_Planned.SelectedPackage && (mission.Category == Mission.MissionCategory.Package || mission.Category == Mission.MissionCategory.Mission) && Client.AirTaskingOrderWindow.Visible && Client.AirTaskingOrderWindow.SelectedMission != mission))
					{
						continue;
					}
					for (int j = mission.FlightList.Count - 1; j >= 0; j += -1)
					{
						Mission.Flight flight = mission.FlightList[j];
						if (!recordConnection.Contains(flight) && !Information.IsNothing(flight.FlightPlan) && flight.FlightPlan.Count() != 0 && (SimConfiguration.DefaultGamePreferences.ShowFlightPlans_Planned != Game.GamePreferences.FlightPlansVisibilitySetting_Planned.SelectedFlight || !Client.AirTaskingOrderWindow.Visible || (!Information.IsNothing(Client.AirTaskingOrderWindow.SelectedFlight) && Operators.CompareString(Client.AirTaskingOrderWindow.SelectedFlight.ObjectID, flight.ObjectID, TextCompare: true) == 0)))
						{
							if (flight.HasCriticalError)
							{
								System.Drawing.Color color_ = System.Drawing.Color.FromArgb(255, System.Drawing.Color.Red);
								List<Mission.Flight> list_ = null;
								CL_DrawFlightPlan(flight, color_, ref list_, ref singletonConnection, System.Drawing.Drawing2D.DashStyle.DashDotDot, System.Drawing.Drawing2D.DashStyle.Dot, null);
							}
							else
							{
								System.Drawing.Color color_2 = System.Drawing.Color.FromArgb(255, System.Drawing.Color.LightGray);
								List<Mission.Flight> list_2 = null;
								CL_DrawFlightPlan(flight, color_2, ref list_2, ref singletonConnection, System.Drawing.Drawing2D.DashStyle.DashDotDot, System.Drawing.Drawing2D.DashStyle.Dot, null);
							}
						}
					}
				}
				catch (Exception ex)
				{
					ProjectData.SetProjectError(ex);
					Exception exception_ = ex;
					exception_?.Data.Add("Error at 200604", exception_.Message);
					GameGeneral.WriteExceptionsToLog(ref exception_);
					if (Debugger.IsAttached)
					{
						Debugger.Break();
					}
					ProjectData.ClearProjectError();
				}
			}
		}
		catch (Exception ex2)
		{
			ProjectData.SetProjectError(ex2);
			Exception exception_2 = ex2;
			exception_2?.Data.Add("Error at 200605", exception_2.Message);
			GameGeneral.WriteExceptionsToLog(ref exception_2);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

