									{
										Waypoint waypoint_3 = route2[l];
										CL_DrawWeaponRoute(ref waypoint_3, color_0, ref pen_);
									}
								}
							}
						}
						if (waypoint_.WeaponeeringList_SecondElement != null)
						{
							foreach (Mission.WeaponeeringEntry item2 in waypoint_.WeaponeeringList_SecondElement)
							{
								if (item2.Route != null)
								{
									Waypoint[] route3 = item2.Route;
									for (int m = 0; m < route3.Length; m++)
									{
										Waypoint waypoint_4 = route3[m];
										CL_DrawWeaponRoute(ref waypoint_4, color_0, ref pen_);
