								}
							}
						}
						if (waypoint_.WeaponeeringList_SecondElementWingman != null)
						{
							foreach (Mission.WeaponeeringEntry item3 in waypoint_.WeaponeeringList_SecondElementWingman)
							{
								if (item3.Route != null)
								{
									Waypoint[] route4 = item3.Route;
									for (int n = 0; n < route4.Length; n++)
									{
										Waypoint waypoint_5 = route4[n];
										CL_DrawWeaponRoute(ref waypoint_5, color_0, ref pen_);
									}
								}
							}
						}
						if (waypoint_.WeaponeeringList_ThirdElement != null)
						{
							foreach (Mission.WeaponeeringEntry item4 in waypoint_.WeaponeeringList_ThirdElement)
							{
								if (item4.Route != null)
								{
									Waypoint[] route5 = item4.Route;
									for (int num3 = 0; num3 < route5.Length; num3++)
									{
										Waypoint waypoint_6 = route5[num3];
										CL_DrawWeaponRoute(ref waypoint_6, color_0, ref pen_);
									}
								}
							}
						}
						if (waypoint_.WeaponeeringList_ThirdElementWingman == null)
						{
							continue;
						}
						foreach (Mission.WeaponeeringEntry item5 in waypoint_.WeaponeeringList_ThirdElementWingman)
