	private void ReadAccount()
	{
		if (ItemExporter.ConnectInterruptibleTemplate.CallInterruptiblePolicy().IsReadyToRender())
		{
			GeoPoint geopoint = ItemExporter.ConnectInterruptibleTemplate.CallInterruptiblePolicy().Renderer.SubjectA.GetGeopoint();
			GeoPoint geopoint2 = ItemExporter.ConnectInterruptibleTemplate.CallInterruptiblePolicy().Renderer.SubjectB.GetGeopoint();
			issuerConnection.DrawOrthodromicLine(System.Drawing.Color.Yellow, 2f, geopoint.Latitude, geopoint.Longitude, geopoint2.Latitude, geopoint2.Longitude);
		}
	}

	private void DisableAccount()
	{
		foreach (Notification_Bark item in Command_Core.GlobalSingleton.GetInstance().Notification_Barks.ToList())
		{
			item.Cycle();
			item.ReAttachToAnchor();
			System.Drawing.Point point = ManagerListenerManager.SetInterruptibleMap(WorldWindow1, item.Position.Latitude, item.Position.Longitude);
			issuerConnection.DrawText(item.Color, point.X, (int)Math.Round((double)(point.Y - 20) - item.Progress * 40.0), item.Messages.ElementAt(0).text, 0.0, (int)Math.Round(item.FontSize), ExWorldWind.FontWeight.Normal, bool_0: false, bool_1: false, "微软雅黑");
		}
	}

	private void UpdateAccount()
	{
		Command_Core.GlobalSingleton instance = Command_Core.GlobalSingleton.GetInstance();
		if (instance.CrossThreadErrorDispatch_entry.Count > 0)
		{
			(ExceptionEntry, string) tuple = instance.CrossThreadErrorDispatch_entry.ElementAt(0);
			instance.CrossThreadErrorDispatch_entry.RemoveAt(0);
			if (!tuple.Item1.UI_Ignored)
			{
				ErrorForm.Open(tuple.Item1, tuple.Item2);
			}
		}
		if (instance.CrossThreadErrorDispatch_str.Count > 0)
		{
			string string_ = instance.CrossThreadErrorDispatch_str.ElementAt(0);
			instance.CrossThreadErrorDispatch_str.RemoveAt(0);
			ErrorForm.Open(string_);
		}
	}

