		List<Balloon> list;
		lock (BalloonsRenderingList)
		{
			list = BalloonsRenderingList.ToList();
		}
		DateTime now = DateTime.Now;
		foreach (Balloon item in list)
		{
			if (item == null || item.Summary == null || item.Summary.Length <= 0)
			{
				continue;
			}
			item.Opacity -= (DateTime.Now - m_PredicateAdvisor).TotalSeconds;
			Rectangle rectangle = issuerConnection.MeasureString(System.Drawing.Color.White, 20, 20, item.Summary);
			int num = 15;
			item.ObservedHeight = rectangle.Height + 30;
			item.ObservedWidth = rectangle.Width + 30;
			System.Drawing.Point point = ManagerListenerManager.SetInterruptibleMap(WorldWindow1, item.Lat, item.Lon);
			int num10 = point.X;
			int num11 = point.Y;
			double num12 = item.Radius * Math.Cos(item.Theta);
			double num13 = item.Radius * Math.Sin(item.Theta);
			double num14 = (double)item.ObservedWidth / 2.0;
			double num15 = (double)item.ObservedHeight / 2.0;
			int num16 = (int)Math.Round((double)num10 - num14 - num12);
			int num17 = (int)Math.Round((double)num11 - num15 - num13);
			item.CanvasLeft = num16;
			item.CanvasTop = num17;
			double num2 = (double)num16 + num14;
			double num3 = (double)num17 + num15;
			double num4 = Math.Min(num2, num2 + num12);
			double num5 = Math.Min(num3, num3 + num13);
			if (num12 < 0.0)
			{
				if (num13 < 0.0)
				{
					item.X1 = 0.0;
					item.Y1 = 0.0;
					item.X2 = num12;
					item.Y2 = num13;
					item.StemCanvasLeft = (int)Math.Round(num4 - num12);
					item.StemCanvasTop = (int)Math.Round(num5 - num13);
				}
				else
				{
					item.X1 = num12;
					item.Y1 = num13;
					item.X2 = 0.0;
					item.Y2 = 0.0;
					item.StemCanvasLeft = (int)Math.Round(num4 - num12);
					item.StemCanvasTop = (int)Math.Round(num5);
				}
			}
			else if (num13 < 0.0)
			{
				item.X1 = 0.0;
				item.Y1 = 0.0;
				item.X2 = num12;
				item.Y2 = num13;
				item.StemCanvasLeft = (int)Math.Round(num4);
				item.StemCanvasTop = (int)Math.Round(num5 - num13);
			}
			else
			{
				item.X1 = 0.0;
				item.Y1 = 0.0;
				item.X2 = num12;
				item.Y2 = num13;
				item.StemCanvasLeft = (int)Math.Round(num4);
				item.StemCanvasTop = (int)Math.Round(num5);
			}
			int num6 = (int)Math.Round(item.Opacity * 255.0);
			if (num6 <= 255)
			{
				if (num6 < 0)
				{
					num6 = 0;
				}
			}
			else
			{
				num6 = 255;
			}
			int canvasLeft = item.CanvasLeft;
			int canvasTop = item.CanvasTop;
			int num7 = num;
			int num8 = rectangle.Width;
			int num9 = rectangle.Height;
			System.Drawing.Color color = System.Drawing.Color.FromArgb(num6, System.Drawing.Color.Black);
			System.Drawing.Color color2 = System.Drawing.Color.FromArgb(num6, System.Drawing.Color.Gray);
			issuerConnection.DrawLine(System.Drawing.Color.FromArgb(num6, System.Drawing.Color.White), (int)Math.Round(item.X1 + (double)item.StemCanvasLeft), (int)Math.Round(item.Y1 + (double)item.StemCanvasTop), (int)Math.Round(item.X2 + (double)item.StemCanvasLeft), (int)Math.Round(item.Y2 + (double)item.StemCanvasTop));
			issuerConnection.FillEllipse(color, color2, canvasLeft + num7 + num8, canvasTop + num7, num7 * 2, num7 * 2);
			issuerConnection.FillEllipse(color, color2, canvasLeft + num7 + num8, canvasTop + num7 + num9, num7 * 2, num7 * 2);
			issuerConnection.FillEllipse(color, color2, canvasLeft + num7, canvasTop + num7, num7 * 2, num7 * 2);
			issuerConnection.FillEllipse(color, color2, canvasLeft + num7, canvasTop + num7 + num9, num7 * 2, num7 * 2);
			issuerConnection.FillRectangle(color, color, canvasLeft + num7, canvasTop, num9 + num7 * 2, num8);
			issuerConnection.FillRectangle(color, color, canvasLeft, canvasTop + num7, num9, num8 + num7 * 2);
			issuerConnection.DrawLine(color2, 2f, canvasLeft, canvasTop + num7, canvasLeft, canvasTop + num7 + num9);
			issuerConnection.DrawLine(color2, 2f, canvasLeft + num8 + num7 * 2, canvasTop + num7, canvasLeft + num8 + num7 * 2, canvasTop + num7 + num9);
			issuerConnection.DrawLine(color2, 2f, canvasLeft + num7, canvasTop, canvasLeft + num7 + num8, canvasTop);
			issuerConnection.DrawLine(color2, 2f, canvasLeft + num7, canvasTop + num9 + num7 * 2, canvasLeft + num7 + num8, canvasTop + num9 + num7 * 2);
			System.Drawing.Color color3 = item.Color;
			issuerConnection.DrawText(System.Drawing.Color.FromArgb(num6, color3.R, color3.G, color3.B), item.CanvasLeft + num, item.CanvasTop + num, item.Summary, 0.0, 18, ExWorldWind.FontWeight.Normal, bool_0: false, bool_1: false, "微软雅黑");
		}
		Balloon[] array = BalloonsRenderingList.ToArray();
		Balloon[] array2 = array;
		foreach (Balloon balloon in array2)
		{
