		int num5 = 50;
		int num6 = 2;
		int num7 = 2;
		int num8 = 10;
		bool flag = true;
		if (notification.HasExpired())
		{
			flag = true;
			notification.TransparencyCountDown -= 3;
			if (notification.TransparencyCountDown <= 0)
			{
				Notification.DeleteNotification();
			}
		}
		if (!flag)
		{
			return;
		}
		notification.BoxWidth = num;
		notification.SidePadding = num8;
