		{
			color = System.Drawing.Color.FromArgb(notification.TransparencyCountDown, 10, 10, 10);
			color2 = System.Drawing.Color.FromArgb(notification.TransparencyCountDown, 50, 50, 50);
			color_ = System.Drawing.Color.FromArgb(notification.TransparencyCountDown, 230, 230, 230);
			color_2 = System.Drawing.Color.FromArgb(notification.TransparencyCountDown, 180, 180, 180);
