		{
			color = System.Drawing.Color.FromArgb(notification.TransparencyCountDown, 60, 0, 0);
			color2 = System.Drawing.Color.FromArgb(notification.TransparencyCountDown, 127, 0, 0);
			color_ = System.Drawing.Color.FromArgb(notification.TransparencyCountDown, 255, 140, 70);
			color_2 = System.Drawing.Color.FromArgb(notification.TransparencyCountDown, 255, 200, 140);
		}
