		issuerConnection.FillRectangle(color, color, num4 + num6, num5 + num6, num3 - num6 * 2, num - num6 * 2);
		int num9 = num7;
		int num10 = notification.ProcessedMultilines_Title.Count - 1;
		for (int i = 0; i <= num10; i++)
		{
			issuerConnection.DrawText(color_, num4 + num8, num5 + num9, notification.ProcessedMultilines_Title[i], 0.0, notification.StringLengthTitle.Height, ExWorldWind.FontWeight.Normal, bool_0: false, bool_1: false, "微软雅黑");
			if (i >= 2)
			{
				i = notification.ProcessedMultilines_Title.Count + 1;
			}
			num9 += num7 + notification.StringLengthTitle.Height;
		}
		num9 += notification.StringLengthTitle.Height;
		int num2 = notification.ProcessedMultilines_Description.Count - 1;
		for (int j = 0; j <= num2; j++)
		{
			issuerConnection.DrawText(color_2, num4 + num8, num5 + num9, notification.ProcessedMultilines_Description[j], 0.0, notification.StringLengthDescription.Height, ExWorldWind.FontWeight.Normal, bool_0: false, bool_1: false, "微软雅黑");
			num9 += num7 + notification.StringLengthDescription.Height;
		}
	}

	private void RestartAccount()
	{
		if (CommandLayer.IsAlaCarteDisabled("CL_DrawSelectedUnitsText"))
		{
			return;
		}
		try
		{
			if (Client.CurrentSide == null || Client.CurrentSide.SelectedUnits.Where((Module_Unit.Unit theU) => theU.IsActiveUnit).Count() <= 0)
			{
				return;
			}
			int num = CaptionBarBottomY + 5;
			int num2 = 16;
			issuerConnection.DrawText(System.Drawing.Color.White, 10, num, "所选单元:", 0.0, 16, ExWorldWind.FontWeight.Normal, bool_0: false, bool_1: true, "微软雅黑");
			num += 17;
			singletonAdvisor.Clear();
			foreach (Module_Unit.Unit selectedUnit in Client.CurrentSide.SelectedUnits)
			{
				if (!selectedUnit.IsActiveUnit)
				{
					continue;
				}
				if (selectedUnit.IsGroup)
				{
					foreach (ActiveUnit value in ((Group)selectedUnit).Units.Values)
					{
						singletonAdvisor.Add(value);
					}
				}
				else
				{
					singletonAdvisor.Add((ActiveUnit)selectedUnit);
				}
			}
			foreach (IGrouping<string, ActiveUnit> item in (from theU in singletonAdvisor
				group theU by theU.UnitClass).ToList())
			{
				issuerConnection.DrawText(System.Drawing.Color.White, 10, num, Conversions.ToString(item.Count()) + "x " + item.ElementAtOrDefault(0).UnitClass, 0.0, num2, ExWorldWind.FontWeight.Normal, bool_0: false, bool_1: true, "微软雅黑");
				num += num2 + 1;
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			DarkMessageBox.ShowError(ex2.Message, "CL Error");
			if (ex2.InnerException != null)
			{
				DarkMessageBox.ShowError(ex2.InnerException.Message, "CL Inner Error");
			}
			ProjectData.ClearProjectError();
		}
	}

