	private void StopAccount()
	{
		if (CommandLayer.IsAlaCarteDisabled("CL_DrawMeasuringLine"))
		{
			return;
		}
		try
		{
			if (Client.CurrentUserAction == Client.UserAction.MeasuringDistance && !StartOfMeasurement.HasZeroCoords)
			{
				m_WriterConnection = new GraphicsPath();
				_SpecificationConnection = new System.Drawing.Pen(System.Drawing.Color.White, 1f);
				Geopoint_Struct geopoint_Struct = ManagerListenerManager.CalculateInterruptibleMap(WorldWindow1, CurrentMousePosition.X, CurrentMousePosition.Y);
				if (!double.IsNaN(geopoint_Struct.Latitude) && !double.IsNaN(geopoint_Struct.Longitude))
				{
					Math2.VerifyClass(StartOfMeasurement.Latitude, StartOfMeasurement.Longitude, geopoint_Struct.Latitude, geopoint_Struct.Longitude);
					m_WriterConnection.AddLine(ManagerListenerManager.SetInterruptibleMap(WorldWindow1, StartOfMeasurement.Latitude, StartOfMeasurement.Longitude), CurrentMousePosition);
					EnableAccount(_SpecificationConnection, m_WriterConnection);
					float num = Math2.VerifyClass(StartOfMeasurement.Latitude, StartOfMeasurement.Longitude, geopoint_Struct.Latitude, geopoint_Struct.Longitude);
					float float_ = Math2.PublishClass(StartOfMeasurement.Latitude, StartOfMeasurement.Longitude, geopoint_Struct.Latitude, geopoint_Struct.Longitude);
					string string_ = ((num < 1f) ? (string.Format("{0:0.0}", num, 5) + "海里 (" + Conversions.ToString((int)Math.Round(num * 1852f)) + " 米) - " + Misc.FillRequest(float_) + "deg") : (string.Format("{0:0.0}", num, 2) + "海里 - " + Misc.FillRequest(float_) + "deg"));
					issuerConnection.DrawText(System.Drawing.Color.White, CurrentMousePosition.X + 10, CurrentMousePosition.Y - 5, string_, 0.0, 18, ExWorldWind.FontWeight.Normal, bool_0: false, bool_1: true, "微软雅黑");
					_SpecificationConnection.Dispose();
					m_WriterConnection.Dispose();
				}
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

	private void CancelAccount()
	{
		if (CommandLayer.IsAlaCarteDisabled("CL_DrawEventEditorAreas"))
		{
			return;
		}
		try
		{
			if (!ItemExporter.ConnectInterruptibleTemplate.EditEvent.Visible && !ItemExporter.ConnectInterruptibleTemplate.ListEvents.Visible && !ItemExporter.ConnectInterruptibleTemplate.ListTriggers.Visible && !ItemExporter.ConnectInterruptibleTemplate.ListActions.Visible)
			{
				return;
			}
			foreach (Command_Core.EventTrigger value in Client.CurrentScenario.EventTriggers.Values)
			{
				switch (value.Type)
				{
				case Command_Core.EventTrigger.EventTriggerType.UnitEntersArea:
				{
					Geopoint_Struct[] array2 = new Geopoint_Struct[((EventTrigger_UnitEntersArea)value).Area.Count - 1 + 1];
					int num2 = ((EventTrigger_UnitEntersArea)value).Area.Count - 1;
					for (_WatcherConnection = 0; _WatcherConnection <= num2; _WatcherConnection++)
					{
						array2[_WatcherConnection] = new Geopoint_Struct(((EventTrigger_UnitEntersArea)value).Area[_WatcherConnection].Longitude, ((EventTrigger_UnitEntersArea)value).Area[_WatcherConnection].Latitude);
					}
					issuerConnection.DrawAreaAlpha(array2, 1, System.Drawing.Color.HotPink, System.Drawing.Color.HotPink, 50);
					break;
				}
				case Command_Core.EventTrigger.EventTriggerType.UnitRemainsInArea:
				{
