	private void RegisterAccount()
	{
		_UtilsAdvisor = "";
		if (CommandLayer.IsAlaCarteDisabled("CL_DrawCoursePreview") || Client.CurrentSide == null || Client.SelectedUnit == null || !Client.SelectedUnit.IsActiveUnit || Client.CurrentUserAction != Client.UserAction.PlottingCourse)
		{
			return;
		}
		ActiveUnit activeUnit = (ActiveUnit)Client.SelectedUnit;
		bool flag = false;
		double latitude;
		double longitude;
		if (activeUnit.Navigator.HasPlottedCourse())
		{
			Waypoint[] plottedCourse = activeUnit.Navigator.PlottedCourse;
			Waypoint waypoint = null;
			Waypoint[] array = plottedCourse;
			Waypoint[] array2 = array;
			foreach (Waypoint waypoint2 in array2)
			{
				if (waypoint2.Category != Waypoint.WaypointCategory.FlightPlan)
				{
					waypoint = waypoint2;
				}
			}
			if (waypoint == null)
			{
				latitude = activeUnit.GetLatitude();
				longitude = activeUnit.GetLongitude();
			}
			else
			{
				latitude = waypoint.Latitude;
				longitude = waypoint.Longitude;
			}
		}
		else
		{
			latitude = activeUnit.GetLatitude();
			longitude = activeUnit.GetLongitude();
		}
		System.Drawing.Color color_ = System.Drawing.Color.FromArgb(255, System.Drawing.Color.LightGray);
		Geopoint_Struct geopoint_Struct = ManagerListenerManager.CalculateInterruptibleMap(WorldWindow1, CurrentMousePosition.X, CurrentMousePosition.Y);
		issuerConnection.DrawOrthodromicLine(color_, 2f, geopoint_Struct.Latitude, geopoint_Struct.Longitude, latitude, longitude);
		Tuple<double, double> tuple = CommandLayer.UTIL_OrthodromicInterpolation(geopoint_Struct.Latitude * CSMath.PI_dividedBy_180, geopoint_Struct.Longitude * CSMath.PI_dividedBy_180, latitude * CSMath.PI_dividedBy_180, longitude * CSMath.PI_dividedBy_180, 0.05);
		System.Drawing.Point point = ManagerListenerManager.SetInterruptibleMap(WorldWindow1, tuple.Item1 * 180.0 / Math.PI, tuple.Item2 * 180.0 / Math.PI);
		double num = Math.PI + Math.Atan2(point.Y - CurrentMousePosition.Y, point.X - CurrentMousePosition.X);
		int num2 = 15;
		double num3 = 15.0 * CSMath.PI_dividedBy_180;
		if (activeUnit.CanPlotCourseToThisLocation(geopoint_Struct.Latitude, geopoint_Struct.Longitude))
		{
			issuerConnection.DrawLine(color_, 2f, CurrentMousePosition.X, CurrentMousePosition.Y, (float)((double)CurrentMousePosition.X - Math.Cos(num + num3) * (double)num2), (float)((double)CurrentMousePosition.Y - Math.Sin(num + num3) * (double)num2));
			issuerConnection.DrawLine(color_, 2f, CurrentMousePosition.X, CurrentMousePosition.Y, (float)((double)CurrentMousePosition.X - Math.Cos(num - num3) * (double)num2), (float)((double)CurrentMousePosition.Y - Math.Sin(num - num3) * (double)num2));
		}
		else
		{
			flag = true;
			color_ = System.Drawing.Color.FromArgb(255, System.Drawing.Color.Red);
			int num4 = (int)Math.Round(Math.Cos(num + num3) * (double)num2);
			int num5 = (int)Math.Round(Math.Sin(num + num3) * (double)num2);
			int num6 = (int)Math.Round(Math.Cos(num - num3) * (double)num2);
			int num7 = (int)Math.Round(Math.Sin(num - num3) * (double)num2);
			issuerConnection.DrawLine(color_, 2f, CurrentMousePosition.X + num4, CurrentMousePosition.Y + num5, CurrentMousePosition.X - num4, CurrentMousePosition.Y - num5);
			issuerConnection.DrawLine(color_, 2f, CurrentMousePosition.X + num6, CurrentMousePosition.Y + num7, CurrentMousePosition.X - num6, CurrentMousePosition.Y - num7);
		}
		float num8 = Math2.VerifyClass(latitude, longitude, geopoint_Struct.Latitude, geopoint_Struct.Longitude);
		float float_ = Math2.PublishClass(latitude, longitude, geopoint_Struct.Latitude, geopoint_Struct.Longitude);
		string text = ((num8 < 1f) ? (string.Format("{0:0.0}", num8, 5) + "海里 (" + Conversions.ToString((int)Math.Round(num8 * 1852f)) + " 米) - " + Misc.FillRequest(float_) + "deg") : (string.Format("{0:0.0}", num8, 2) + "海里 - " + Misc.FillRequest(float_) + "deg"));
		if (flag)
		{
			text = ((SimConfiguration.DefaultGamePreferences.MapCursorBox == Game.GamePreferences.MapCursorBoxVisibilitySetting.AtCursor) ? (text + " ") : (text + "\r\n"));
			text += "(距离太远无法导航到此处)";
		}
		issuerConnection.DrawText(System.Drawing.Color.White, CurrentMousePosition.X + 15, CurrentMousePosition.Y + 5, text, 0.0, 18, ExWorldWind.FontWeight.Normal, bool_0: false, bool_1: true, "微软雅黑");
		_UtilsAdvisor = text;
	}

