							break;
						}
						break;
					case Contact_Base.ContactType.NavalBase:
						switch (contact.GetStance(Client.CurrentSide))
						{
						case Misc.PostureStance.Neutral:
							text2 = "Installation_neutral.png";
							break;
						case Misc.PostureStance.Friendly:
							text2 = "Installation_friendly.png";
							break;
						case Misc.PostureStance.Unfriendly:
							text2 = "Installation_unfriendly.png";
							break;
						case Misc.PostureStance.Hostile:
							text2 = "Installation_hostile.png";
							break;
						case Misc.PostureStance.Unknown:
							text2 = "Installation_unknown.png";
							break;
						}
						break;
					case Contact_Base.ContactType.MobileGroup:
						switch (contact.GetStance(Client.CurrentSide))
						{
						case Misc.PostureStance.Neutral:
							text2 = "mobile_neutral.png";
							break;
						case Misc.PostureStance.Friendly:
							text2 = "mobile_friendly.png";
							break;
						case Misc.PostureStance.Unfriendly:
							text2 = "mobile_unfriendly.png";
							break;
						case Misc.PostureStance.Hostile:
							text2 = "mobile_hostile.png";
							break;
						case Misc.PostureStance.Unknown:
							text2 = "mobile_unknown.png";
							break;
						}
						break;
					}
					if (contact.ActualUnit != null && contact.ActualUnit.GetisTaggedAsDecoyByThisSide(Client.CurrentSide.ObjectID))
					{
						text2 = "air_decoy_" + text;
						return text2;
					}
				}
			}
			return text2;
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
