	private void ValidateState()
	{
		try
		{
			if (Client.MapVisibleUnits == null || Client.MapVisibleUnits.Count == 0)
			{
				return;
			}
			List<Module_Unit.Unit> list = Client.MapVisibleUnits.OrderBy((Module_Unit.Unit theU) => theU.GetCurrentAltitude()).ToList();
			m_MockAdvisor.Clear();
			Parallel.ForEach(list, delegate(Module_Unit.Unit unit_0)
			{
				if (unit_0.IsActiveUnit && ((ActiveUnit)unit_0).Sensory.JammerUnitsAreAffectingMe)
				{
					m_MockAdvisor.TryAdd(unit_0.ObjectID, unit_0.ObjectID);
				}
			});
			ViewState();
			foreach (Module_Unit.Unit item in list)
			{
				if (item.IsActiveUnit)
				{
					DeleteState((ActiveUnit)item);
				}
				else
				{
					ManageAccount((Contact)item);
				}
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

