	private void NewState(object sender, EventArgs e)
	{
		if (Client.CurrentSide == null)
		{
			return;
		}
		foreach (Module_Unit.Unit selectedUnit in Client.CurrentSide.SelectedUnits)
		{
			bool flag = false;
			if (Information.IsNothing(selectedUnit) || !selectedUnit.IsActiveUnit)
			{
				continue;
			}
			if ((object)selectedUnit.GetType() == typeof(Aircraft))
			{
				Aircraft aircraft = (Aircraft)selectedUnit;
				if (aircraft.Loadout.Cargo_ParadropCapable)
				{
					aircraft.AirOps.UnloadCargoParadrop();
					flag = true;
				}
				if (aircraft.OnboardCargo.Count() != 0 && aircraft.IsHelicopter)
				{
					aircraft.AirOps.Condition = Aircraft_AirOps._AirOpsCondition.TransferringCargo;
					aircraft.AirOps.ConditionTimer = Math.Max(120, ActiveUnit_DockingOps.TimeToUnloadCargo(aircraft, aircraft.OnboardCargo.ToList()));
					flag = true;
				}
			}
			else if (selectedUnit.IsGroup)
			{
				if ((selectedUnit is Group) & ((Group)selectedUnit).IsLandInstallation)
				{
					foreach (ActiveUnit value in ((Group)selectedUnit).Units.Values)
					{
						if (value.OnboardCargo.Count() > 0)
						{
							Cargo.UnloadCargoAtLocation(value, ref value.OnboardCargo, null, value.GetLatitude(), value.GetLongitude(), value.ParentScen, value.GetUnitSide(), bool_0: false);
							break;
						}
					}
				}
			}
			else
			{
				ActiveUnit activeUnit = (ActiveUnit)selectedUnit;
				if (activeUnit.DockingOps.RegisterClient())
				{
					activeUnit.DockingOps.SettleForCargoTransfer();
				}
			}
			if (!selectedUnit.IsGroup && ((ActiveUnit)selectedUnit).OnboardCargo.Count() > 0 && !flag)
			{
				((ActiveUnit)selectedUnit).AddMessage(selectedUnit.Name + "无法在这里卸货", "Cannot unload cargo", LoggedMessage.MessageType.UI, 0, bool_0: false, new Geopoint_Struct(selectedUnit.GetLongitude(), selectedUnit.GetLatitude()));
			}
		}
	}

