	private void InitState()
	{
		_ = Client.MainFormShownComplete;
	}

	private void CheckState(object sender, EventArgs e)
	{
		m_MapperRef.PositionCorrectlyWithinMainform(this);
		ElementHost_RightColumnWPF.Visible = false;
		ElementHost_RightColumnWPF.Left = base.Width;
		Button_SlideRightColumn.Left = base.Width - Button_SlideRightColumn.Width - 15;
		if (Client.SelectedUnit != null)
		{
			if (m_TagAdvisor > 0)
			{
				Slide_RC_Out();
			}
			m_TagAdvisor++;
		}
	}

	private void ConcatState(object sender, EventArgs e)
	{
		if (ElementHost_RightColumnWPF.Visible)
		{
			Slide_RC_Out();
		}
		else
		{
			Slide_RC_In();
		}
	}

	public void Slide_RC_Out()
	{
		ElementHost_RightColumnWPF.Visible = false;
		Button_SlideRightColumn.Left = base.Width - Button_SlideRightColumn.Width - 15;
		ElementHost_RightColumnWPF.Left = base.Width;
		Button_SlideRightColumn.Image = Image.FromFile(GlobalVariables.ApplicationStartupPath + "\\Symbols\\Menu\\ArrowWhiteLeft.gif");
		DrawArgs.Instance.XOffset = 0;
	}

	public void Slide_RC_In()
	{
		ElementHost_RightColumnWPF.Visible = true;
		if (SimConfiguration.DefaultGamePreferences.StartFullScreen)
		{
			ElementHost_RightColumnWPF.Left = base.Width - ElementHost_RightColumnWPF.Width;
		}
		else
		{
			ElementHost_RightColumnWPF.Left = base.Width - ElementHost_RightColumnWPF.Width - 14;
		}
		Button_SlideRightColumn.Left = ElementHost_RightColumnWPF.Left - Button_SlideRightColumn.Width - 5;
		Button_SlideRightColumn.Image = Image.FromFile(GlobalVariables.ApplicationStartupPath + "\\Symbols\\Menu\\ArrowWhiteRight.gif");
		DrawArgs.Instance.XOffset = 270;
	}

	private void InterruptState()
	{
		Client.theElementHostRightColumn = ElementHost_RightColumnWPF;
		ElementHost_RightColumnWPF.Visible = false;
		ElementHost_RightColumnWPF.Left = base.Width;
		Button_SlideRightColumn.Left = base.Width - Button_SlideRightColumn.Width - 15;
	}

	public void SetRenderCountdown(double double_0)
	{
		if (fieldAdvisor < double_0)
		{
			fieldAdvisor = double_0;
		}
	}

