			WorldWindow1.Height = Panel_WW.Height;
			WorldWindow1.Size = new System.Drawing.Size(Panel_WW.Width, Panel_WW.Height);
		}
		if (!Client.MainFormShownComplete)
		{
			return;
		}
		RefreshCaption();
		if (!regAdvisor)
		{
			regAdvisor = true;
			try
			{
				if ((_StateCode != null) & !m_HelperCode)
				{
					_StateCode.SetDateTime(Client.CurrentScenario.Time);
					_StateCode.SetProjection(Convert.ToSingle(GetMapCenter().Longitude), Convert.ToSingle(GetMapCenter().Latitude), CameraAltitude);
					if (infoCode)
					{
						_StateCode.OnResize(WorldWindow1);
						infoCode = false;
					}
					if (authenticationCode)
					{
						_StateCode.ClearTiles();
						authenticationCode = false;
					}
					WorldWindow1.bool_0 = m_HelperCode;
				}
				try
				{
					WorldWindow1.Refresh();
				}
				catch (Exception ex)
				{
					ProjectData.SetProjectError(ex);
					Exception exception_ = ex;
					GameGeneral.WriteLogDebugInfoToFile("DXNTRACE-DRAW: WorldWindow1 refresh exception:");
					GameGeneral.WriteExceptionsToLog(ref exception_);
					ProjectData.ClearProjectError();
				}
			}
			finally
			{
				regAdvisor = false;
			}
		}
		Client.MustRefreshMainForm = false;
	}

