	public void HandleMouseHoverOrder()
	{
		Client.CurrentUserAction_Hovering = Client.UserAction.None;
		if (Client.SelectedUnit == null || Client.SetConfiguration() == null || Operators.CompareString(Client.SelectedUnit.ObjectID, Client.SetConfiguration().ObjectID, TextCompare: true) == 0 || Client.CurrentSide.SelectedUnits.Count == 0 || !Client.SelectedUnit.IsActiveUnit || !Client.SelectedUnit.GetUnitSide().IsHumanControlled || !Client.CurrentSide.SelectedUnits.Contains(Client.SelectedUnit))
		{
			return;
		}
		if (Client.SetConfiguration().DisableWriter())
		{
			Contact contact = (Contact)Client.SetConfiguration();
			if (contact.GetStance(Client.SelectedUnit.GetUnitSide()) != Misc.PostureStance.Hostile && contact.GetStance(Client.SelectedUnit.GetUnitSide()) != Misc.PostureStance.Friendly && contact.IDStatus != Contact_Base.IdentificationStatus.PreciseID)
			{
				Client.CurrentUserAction_Hovering = Client.UserAction.HoveringOnInteractableContact;
			}
			else if (contact.GetStance(Client.SelectedUnit.GetUnitSide()) != Misc.PostureStance.Friendly)
			{
				Client.CurrentUserAction_Hovering = Client.UserAction.HoveringOnInteractableContact;
			}
		}
		else
		{
			if (!Client.SetConfiguration().IsActiveUnit)
			{
				return;
			}
			if (Client.SetConfiguration().GetUnitSide().GetConsidersThisSideToBe(Client.SelectedUnit.GetUnitSide()) == Misc.PostureStance.Hostile)
			{
				Client.CurrentUserAction_Hovering = Client.UserAction.HoveringOnInteractableContact;
			}
			else
			{
				if (Client.SetConfiguration().GetUnitSide() != Client.CurrentSide && !Module_Side.IsAlliedWithThisSide(Client.SetConfiguration().GetUnitSide(), Client.CurrentSide))
				{
					return;
				}
				ActiveUnit activeUnit_ = (ActiveUnit)Client.SetConfiguration();
				if (Client.SelectedUnit.IsAircraft && Client.SetConfiguration().IsAircraft)
				{
					Aircraft aircraft = (Aircraft)Client.SelectedUnit;
					if (aircraft.AirOps.StartProxy(ref activeUnit_) && Control.ModifierKeys != Keys.Shift)
					{
						Client.CurrentUserAction_Hovering = Client.UserAction.HoveringOnInteractableContact;
					}
					else if (activeUnit_.AssignedMissionOrPackage() != null && (aircraft.AssignedMissionOrPackage() == null || (aircraft.AssignedMissionOrPackage() != null && Operators.CompareString(aircraft.AssignedMissionOrPackage().ObjectID, activeUnit_.AssignedMissionOrPackage().ObjectID, TextCompare: true) != 0)))
					{
						Client.CurrentUserAction_Hovering = Client.UserAction.HoveringOnInteractableContact;
					}
				}
				else
				{
					if (!Client.SelectedUnit.IsAircraft || Client.SetConfiguration().IsGroup)
					{
						return;
					}
					ActiveUnit activeUnit = (ActiveUnit)Client.SetConfiguration();
					if (activeUnit.HasAirFacilities)
					{
						Aircraft aircraft2 = (Aircraft)Client.SelectedUnit;
						if (Operators.CompareString(activeUnit.ObjectID, aircraft2.AirOps.ActualDestinationHost.ObjectID, TextCompare: true) == 0)
						{
							Client.CurrentUserAction_Hovering = Client.UserAction.HoveringOnInteractableContact;
						}
						else if (activeUnit.AirOps.CanHostThisAircraft((Aircraft)Client.SelectedUnit) == AirOpsAttemptResult.Success)
						{
							Client.CurrentUserAction_Hovering = Client.UserAction.HoveringOnInteractableContact;
						}
					}
				}
			}
		}
	}

