	private void SetState(object sender, EventArgs e)
	{
		switch (Client.CurrentUserAction)
		{
		case Client.UserAction.PlottingCourse:
			WorldWindow1.Cursor = Cursors.Cross;
			break;
		case Client.UserAction.AddingPlatform:
			WorldWindow1.Cursor = Cursors.Hand;
			break;
		case Client.UserAction.None:
			WorldWindow1.Cursor = Cursors.Default;
			break;
		}
		ResolveAuthentication();
		CheckProducer().Start();
	}

