	private void CalculateState(object sender, MouseEventArgs e)
	{
		try
		{
			SetIsPointAreaSelecting(bool_0: false);
			SetIsSelectingArea(bool_0: false);
			serviceAdvisor = e;
			if (!m_IdentifierAdvisor.Contains(e.Location) || _BroadcasterAdvisor >= SystemInformation.DoubleClickTime)
			{
				RestartInterruptibleConfig().Stop();
				m_CandidateAdvisor = true;
				m_BaseAdvisor = false;
				m_PolicyAdvisor = false;
				_BroadcasterAdvisor = 0;
			}
			if (m_CandidateAdvisor)
			{
				bool flag = false;
				switch (Client.CurrentUserAction)
				{
				case Client.UserAction.PlottingCourse:
					flag = true;
					break;
				case Client.UserAction.MeasuringDistance:
					flag = true;
					break;
				}
				if (flag)
				{
					m_CandidateAdvisor = false;
					m_IdentifierAdvisor = new Rectangle((int)Math.Round((double)e.X - (double)SystemInformation.DoubleClickSize.Width / 2.0), (int)Math.Round((double)e.Y - (double)SystemInformation.DoubleClickSize.Height / 2.0), SystemInformation.DoubleClickSize.Width, SystemInformation.DoubleClickSize.Height);
					RestartInterruptibleConfig().Start();
				}
				CompareState(RuntimeHelpers.GetObjectValue(sender));
			}
			else if (m_IdentifierAdvisor.Contains(e.Location) && _BroadcasterAdvisor < SystemInformation.DoubleClickTime)
			{
				m_BaseAdvisor = true;
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception exception_ = ex;
			exception_?.Data.Add("Error at 200354", exception_.Message);
			GameGeneral.WriteExceptionsToLog(ref exception_);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

	private void PopState(object sender, MouseEventArgs e)
	{
		if (m_AlgoAdvisor)
		{
			m_AlgoAdvisor = false;
		}
		else
		{
			CreateState(RuntimeHelpers.GetObjectValue(sender));
		}
	}

	public void doubleClickTimer_Tick(object sender, EventArgs e)
	{
		_BroadcasterAdvisor += 100;
		if (_BroadcasterAdvisor < SystemInformation.DoubleClickTime)
		{
			if (m_BaseAdvisor)
			{
				InstantiateState();
				RestartInterruptibleConfig().Stop();
			}
		}
		else
		{
			RestartInterruptibleConfig().Stop();
		}
	}

	private void InstantiateState()
	{
		try
