			if (serviceAdvisor.Button == MouseButtons.Left)
			{
				switch (Client.CurrentUserAction)
				{
				case Client.UserAction.PlottingCourse:
				case Client.UserAction.PlottingCourseForSalvo:
				{
					Client.CurrentUserAction = Client.UserAction.None;
