					Module_Unit.Unit unitClicked = GetUnitClicked(RuntimeHelpers.GetObjectValue(object_0), Client.CurrentMapProfile.ViewMode, serviceAdvisor);
					if (!Information.IsNothing(unitClicked) && unitClicked.IsActiveUnit && (unitClicked.GetUnitSide() == Client.CurrentSide || Module_Side.IsAlliedWithThisSide(unitClicked.GetUnitSide(), Client.CurrentSide)) && (object)unitClicked.GetType() != typeof(Weapon))
					{
