					}
					MapRender_UI();
					break;
				}
				case Client.UserAction.AddingPlatform:
					break;
				}
			}
			if (serviceAdvisor.Button == MouseButtons.Right)
			{
				Geopoint_Struct geopoint_Struct_2 = ManagerListenerManager.CalculateInterruptibleMap(WorldWindow1, serviceAdvisor.X, serviceAdvisor.Y);
				_DispatcherConnection = Math2.CancelClass(GetMapCenter().Latitude, GetMapCenter().Longitude, geopoint_Struct_2.Latitude, geopoint_Struct_2.Longitude);
				listenerConnection = Math2.PublishClass(GetMapCenter().Latitude, GetMapCenter().Longitude, geopoint_Struct_2.Latitude, geopoint_Struct_2.Longitude);
				if (Client.CurrentUserAction == Client.UserAction.None)
				{
					Module_Unit.Unit unitClicked2 = GetUnitClicked(RuntimeHelpers.GetObjectValue(object_0), Client.CurrentMapProfile.ViewMode, serviceAdvisor);
					Client.FillConfiguration(unitClicked2);
					Module_Unit.Unit unit8 = unitClicked2;
					if (Control.ModifierKeys == Keys.Control && geopoint_Struct_2.Latitude >= -90.0 && geopoint_Struct_2.Latitude <= 90.0)
					{
						AddPlatformToolStripMenuItem.Visible = Client.CurrentGame.GameMode == Game._GameMode.ScenEdit;
						UpdateGetter().Show(WorldWindow1, serviceAdvisor.X, serviceAdvisor.Y);
					}
					if (!UpdateState(geopoint_Struct_2) && Client.CurrentScenario.ActiveUnits.Count > 0 && !Information.IsNothing(unit8))
					{
						m_AlgoAdvisor = true;
						if (!Client.CurrentSide.SelectedUnits.Contains(unit8) && !IsSelectingArea() && Control.ModifierKeys != Keys.Shift)
						{
							Client.CurrentSide.SelectedUnits_Clear();
						}
						if (Control.ModifierKeys == Keys.Shift)
						{
							Client.SelectThisUnit(unit8, bool_0: false);
						}
						else
						{
							Client.SelectThisUnit(unit8, bool_0: true);
						}
						if (unit8.IsActiveUnit)
						{
							ShowUnitContextMenu(unit8, serviceAdvisor.X, serviceAdvisor.Y);
						}
						if (unit8.DisableWriter())
						{
							ShowContactContextMenu(unit8, serviceAdvisor.X, serviceAdvisor.Y);
						}
					}
				}
				if (Client.CurrentScenario.ActiveUnits.Count > 0 && !Information.IsNothing(Client.SelectedWaypoint))
				{
					CMenu_Waypoint.Show(WorldWindow1, serviceAdvisor.X, serviceAdvisor.Y);
				}
			}
			if (!Information.IsNothing(Client.SelectedUnit) && Client.SelectedUnit.IsActiveUnit && !((ActiveUnit)Client.SelectedUnit).Navigator.HasFlightPlan)
			{
				ItemExporter.ConnectInterruptibleTemplate.SpeedAlt.SpeedAlt_FlightPlanWaypoint = null;
				ItemExporter.ConnectInterruptibleTemplate.SpeedAlt.SpeedAlt_Flight = null;
				ItemExporter.ConnectInterruptibleTemplate.SpeedAlt.SpeedAlt_Mission = null;
				ItemExporter.ConnectInterruptibleTemplate.SpeedAlt.SpeedAlt_SelectedUnit = (ActiveUnit)Client.SelectedUnit;
				ItemExporter.ConnectInterruptibleTemplate.SpeedAlt.LoadForm();
			}
			else
			{
				if (Information.IsNothing(Client.SelectedWaypoint))
				{
					return;
				}
				if (Client.SelectedWaypoint.Category == Waypoint.WaypointCategory.FlightPlan)
				{
					ItemExporter.ConnectInterruptibleTemplate.SpeedAlt.SpeedAlt_FlightPlanWaypoint = Client.SelectedWaypoint;
					ItemExporter.ConnectInterruptibleTemplate.SpeedAlt.SpeedAlt_Flight = null;
					ItemExporter.ConnectInterruptibleTemplate.SpeedAlt.SpeedAlt_Mission = null;
					bool flag4 = false;
					Side[] sides_ReadOnly = Client.CurrentScenario.Sides_ReadOnly;
					for (int num11 = 0; num11 < sides_ReadOnly.Length; num11++)
					{
						foreach (Mission mission in sides_ReadOnly[num11].Missions)
						{
							if (!mission.TestValue())
							{
								continue;
							}
							foreach (Mission.Flight flight in mission.FlightList)
							{
								Waypoint[] flightPlan2 = flight.FlightPlan;
								for (int num13 = 0; num13 < flightPlan2.Length; num13 = checked(num13 + 1))
								{
									if (flightPlan2[num13] == Client.SelectedWaypoint)
									{
										ItemExporter.ConnectInterruptibleTemplate.SpeedAlt.SpeedAlt_Flight = flight;
										ItemExporter.ConnectInterruptibleTemplate.SpeedAlt.SpeedAlt_Mission = mission;
										flag4 = true;
										break;
									}
								}
								if (flag4)
								{
									break;
								}
							}
							if (!flag4)
							{
								continue;
							}
							break;
						}
						if (flag4)
						{
							break;
						}
					}
					ItemExporter.ConnectInterruptibleTemplate.SpeedAlt.SpeedAlt_SelectedUnit = null;
					ItemExporter.ConnectInterruptibleTemplate.SpeedAlt.LoadForm();
				}
				else
				{
					ItemExporter.ConnectInterruptibleTemplate.SpeedAlt.SpeedAlt_FlightPlanWaypoint = null;
					ItemExporter.ConnectInterruptibleTemplate.SpeedAlt.SpeedAlt_Flight = null;
					ItemExporter.ConnectInterruptibleTemplate.SpeedAlt.SpeedAlt_Mission = null;
					ItemExporter.ConnectInterruptibleTemplate.SpeedAlt.LoadForm();
				}
			}
		}
		catch (Exception ex4)
		{
			ProjectData.SetProjectError(ex4);
			Exception exception_2 = ex4;
			exception_2?.Data.Add("Error at 200350", exception_2.Message);
			GameGeneral.WriteExceptionsToLog(ref exception_2);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

