						}
					}
				}
				else if (Client.SetConfiguration() != null && Client.SetConfiguration().IsActiveUnit)
				{
					if (Client.SetConfiguration().GetUnitSide() != Client.CurrentSide && !Module_Side.IsAlliedWithThisSide(Client.SetConfiguration().GetUnitSide(), Client.CurrentSide))
					{
						flag3 = true;
						flag4 = !Client.SetConfiguration().IsSatellite && !Client.SelectedUnit.IsSatellite;
					}
					else
					{
						ActiveUnit activeUnit_ = (ActiveUnit)Client.SetConfiguration();
						if (Client.SetConfiguration().GetUnitSide() == Client.CurrentSide && (Client.SelectedUnit.IsShip || Client.SelectedUnit.IsAircraft) && (activeUnit_.IsFacility || activeUnit_.IsVehicle))
