	private void InsertState(object sender, EventArgs e)
	{
		Zone zone = (Zone)((DarkToolStripMenuItem)sender).Tag;
		if (Information.IsNothing(zone) || Information.IsNothing(Client.CurrentSide))
		{
			return;
		}
		DialogResult dialogResult = DarkMessageBox.ShowWarning("Also delete the associated reference points?", "Deleting a Zone", DarkDialogButton.YesNoCancel);
		if (dialogResult == DialogResult.Cancel || Client.CurrentSide == null || !Client.CurrentSide.StandardZones.Contains(zone))
		{
			return;
		}
		if (dialogResult == DialogResult.Yes && zone.Area.Count > 0)
		{
			int num = zone.Area.Count - 1;
			for (int i = 0; i <= num; i++)
			{
				Client.CurrentSide.RefPoints.Remove(zone.Area[i]);
			}
		}
		zone.Area.Clear();
		Client.CurrentSide.StandardZones.Remove(zone);
	}

