	private void RestartState(object sender, EventArgs e)
	{
		RecordMap recordMap = (RecordMap)((DarkToolStripMenuItem)sender).Tag;
		Mission mission = null;
		string string_ = recordMap.exceptionMap.ToString() + " patrol (" + recordMap.attrMap.Description + ")";
		mission = new Patrol(Client.CurrentSide, Client.CurrentScenario, string_, Mission.MissionCategory.Mission, recordMap.attrMap.Area, recordMap.exceptionMap, bool_0: true);
		switch (recordMap.exceptionMap)
		{
		case GlobalVariables.PatrolType.ASW:
			mission.FlightSize = 1;
			break;
		case GlobalVariables.PatrolType.ASuW_Naval:
			mission.FlightSize = 1;
			break;
		case GlobalVariables.PatrolType.AAW:
			mission.FlightSize = 2;
			break;
		case GlobalVariables.PatrolType.ASuW_Land:
			mission.FlightSize = 2;
			break;
		case GlobalVariables.PatrolType.ASuW_Mixed:
			mission.FlightSize = 2;
			break;
		case GlobalVariables.PatrolType.SEAD:
			mission.FlightSize = 2;
			break;
		case GlobalVariables.PatrolType.SeaControl:
			mission.FlightSize = 1;
			break;
		}
		mission.SetStatus(Client.CurrentScenario, Mission.MissionStatus.Active);
		List<Aircraft> list = null;
		foreach (Module_Unit.Unit selectedUnit in Client.CurrentSide.SelectedUnits)
		{
			if (selectedUnit.IsFacility)
			{
				list = ((Facility)selectedUnit).AirOps.EmbarkedAircraft_ReadOnly;
			}
			else if (selectedUnit.IsShip)
			{
				list = ((Ship)selectedUnit).AirOps.EmbarkedAircraft_ReadOnly;
			}
			if (list != null)
			{
				foreach (Aircraft item in list)
				{
					Scenario scenario_ = Client.CurrentScenario;
					ActiveUnit activeUnit_ = item;
					bool bool_ = false;
					item.CollectIssuer(ref scenario_, ref activeUnit_, ref mission, ref bool_);
				}
			}
			if ((selectedUnit.IsActiveUnit && !selectedUnit.IsFixedFacility && !selectedUnit.IsSatellite) & !selectedUnit.IsWeapon)
			{
				ActiveUnit activeUnit_2 = (ActiveUnit)selectedUnit;
				ActiveUnit activeUnit = activeUnit_2;
				Scenario scenario_2 = Client.CurrentScenario;
				bool bool_2 = false;
				activeUnit.CollectIssuer(ref scenario_2, ref activeUnit_2, ref mission, ref bool_2);
			}
		}
		Client.CurrentGame.Pause();
		Client.MissionEditorWindow.SelectedMissionLink = mission;
		if (Client.MissionEditorWindow.Visible)
		{
			Client.MissionEditorWindow.RefreshAll();
		}
		else
		{
			Client.MissionEditorWindow.Show();
		}
	}

