	public void ShowEmbeddedMessageLog()
	{
		if (MessageLogControlViewModel.LogCollapsed)
		{
			MessageLogControlElementHost1.MaximumSize = new System.Drawing.Size(MessageLogControlViewModel.MainFormLogWidth, 30);
			MessageLogControlElementHost1.MinimumSize = new System.Drawing.Size(MessageLogControlViewModel.MainFormLogWidth, 30);
			if (MessageLogControlElementHost1.Height > 30)
			{
				MessageLogControlElementHost1.Location = new System.Drawing.Point(MessageLogControlElementHost1.Location.X, MessageLogControlElementHost1.Location.Y + 370);
			}
			MessageLogControlElementHost1.Height = 30;
			MessageLogControlViewModel.LogCollapseButtonRotation = 180.0;
		}
		objectError.DataContext = MessageLogControlViewModel;
		MessageLogControlElementHost1.Visible = true;
		MessageLogControlElementHost1.Invalidate();
		if (SimConfiguration.DefaultGamePreferences.MessageLogInWindow)
		{
			SimConfiguration.DefaultGamePreferences.MessageLogInWindow = false;
			if (WindowPlacement.WindowPlacementSettings.ContainsKey("MessageLogWindow"))
			{
				WindowPlacement.WindowPlacementSettings.Remove("MessageLogWindow");
			}
			SimConfiguration.SaveSettings(WindowPlacement.WindowPlacementSettings, Client.RecentFilenames);
		}
	}

