	internal void MapState()
	{
		try
		{
			_image_StartResume = Image.FromFile(System.Windows.Forms.Application.StartupPath + "\\Symbols\\Menu\\Play.gif");
			_image_StopPause = Image.FromFile(System.Windows.Forms.Application.StartupPath + "\\Symbols\\Menu\\Stop_16.gif");
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception exception_ = ex;
			exception_?.Data.Add("Error at 666", exception_.Message);
			GameGeneral.WriteExceptionsToLog(ref exception_);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

	public void ScenarioReferenceCleanup()
	{
		try
		{
			CurrentlySelectedUnitInSelectedTargetCM = null;
			RegisteredIndicators.Clear();
			recordConnection.Clear();
			ruleConnection.Clear();
			m_RegistryConnection = null;
			m_DefinitionConnection = null;
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception exception_ = ex;
			exception_?.Data.Add("Error at 2000540124", exception_.Message);
			GameGeneral.WriteExceptionsToLog(ref exception_);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

	public void PeriodicHardGC()
	{
		GC.Collect();
		observerConnection = 3600f;
	}

	public void HandleGameModeChanged()
	{
		switch (Client.CurrentGame.GameMode)
		{
		case Game._GameMode.MultiPlayer:
			TSMI_Editor.Visible = false;
			TSMI_Campaign.Visible = false;
			LockSelectedRefPointsToolStripMenuItem.Visible = false;
			UnlockSelectedRefPointsToolStripMenuItem.Visible = false;
			{
				foreach (IEventExporter item in Exporter_General.EventExporters_Interactive)
				{
					item.IsOperating = false;
				}
				return;
			}
		case Game._GameMode.ScenEdit:
			TSMI_Editor.Visible = true;
			TSMI_Campaign.Visible = true;
			LockSelectedRefPointsToolStripMenuItem.Visible = true;
			UnlockSelectedRefPointsToolStripMenuItem.Visible = true;
			{
				foreach (IEventExporter item2 in Exporter_General.EventExporters_Interactive)
				{
					if (item2.ExporterType == IEventExporter.EventExporterType.TacviewPipe && ConfigurationRegistryFilter.PublishInterruptibleMap().Count == 0)
					{
						item2.IsOperating = false;
					}
					else
					{
						item2.IsOperating = true;
					}
				}
				return;
			}
		case Game._GameMode.MultiplayerScenEdit:
			TSMI_Editor.Visible = true;
			TSMI_Campaign.Visible = true;
			LockSelectedRefPointsToolStripMenuItem.Visible = true;
			UnlockSelectedRefPointsToolStripMenuItem.Visible = true;
			{
				foreach (IEventExporter item3 in Exporter_General.EventExporters_Interactive)
