	private void RateState()
	{
		if (Client.CurrentGame.Status == Game._GameStatus.Running)
		{
			List<NewMessageForm> list = new List<NewMessageForm>();
			list.AddRange(Client.OpenMessageWindows.Values);
			foreach (NewMessageForm item in list)
			{
				item.Close();
			}
		}
		switch (Client.CurrentGame.Status)
		{
		case Game._GameStatus.Running:
			m_ConfigCode.Dispatcher.Invoke(delegate
			{
				m_ConfigCode.PlayButton.Visibility = Visibility.Collapsed;
				m_ConfigCode.PauseButton.Visibility = Visibility.Visible;
			});
			break;
		case Game._GameStatus.Paused:
			m_ConfigCode.Dispatcher.Invoke(delegate
			{
				m_ConfigCode.PlayButton.Visibility = Visibility.Visible;
				m_ConfigCode.PauseButton.Visibility = Visibility.Collapsed;
			});
			break;
		}
		Client.MustRefreshMainForm = true;
	}

