	public void GroupUnits()
	{
		if (Client.CurrentSide == null || Client.CurrentSide.SelectedUnits.Count <= 1)
		{
			return;
		}
		List<ActiveUnit> list = new List<ActiveUnit>();
		foreach (ActiveUnit item in Client.CurrentSide.SelectedUnits.Where((Module_Unit.Unit theU) => !theU.DisableWriter()).ToList())
		{
			if (Information.IsNothing(item.GetUnitSide()) || item.GetUnitSide() != Client.CurrentSide)
			{
				continue;
			}
			try
			{
				ActiveUnit activeUnit2 = item;
				if (!activeUnit2.IsGroupMember() && (item.IsPlatform || item.IsGroup))
				{
					list.Add(activeUnit2);
					activeUnit2.Doctrine.ClearCachedParentDoctrine();
					activeUnit2.Sensory.vmethod_0(activeUnit2.Sensors_Cached);
				}
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception exception_ = ex;
				exception_?.Data.Add("Error at 200125", exception_.Message);
				GameGeneral.WriteExceptionsToLog(ref exception_);
				if (Debugger.IsAttached)
				{
					Debugger.Break();
				}
				ProjectData.ClearProjectError();
			}
		}
		if (list.Count <= 1)
		{
			return;
		}
		IEnumerable<ActiveUnit> source = list.Where((ActiveUnit theAU) => theAU.IsGroup);
		switch (source.Count())
		{
		default:
			DarkMessageBox.ShowError("一个单元不能加入多个编组。建议只选择一个编组而解散其它编组。", "Sorry!");
			break;
		case 1:
		{
			IEnumerable<ActiveUnit> enumerable = list.Where((ActiveUnit theAU) => !theAU.IsGroup);
			Group group = (Group)source.ElementAtOrDefault(0);
			int num = 0;
			foreach (ActiveUnit item2 in enumerable)
			{
				if (group.Type == Group.GroupType.AirGroup)
				{
					if (!item2.IsAircraft || (group.GroupLead != null && Operators.CompareString(group.GroupLead.UnitClass, item2.UnitClass, TextCompare: true) != 0))
					{
						continue;
					}
				}
				else if (group.Type == Group.GroupType.SurfaceGroup)
				{
					if (!item2.IsShip)
					{
						continue;
					}
				}
				else if (group.Type == Group.GroupType.SubGroup)
				{
					if (!item2.IsSubmarine)
					{
						continue;
					}
				}
				else if ((group.Type == Group.GroupType.AirBase || group.Type == Group.GroupType.Installation || group.Type == Group.GroupType.MobileGroup || group.Type == Group.GroupType.NavalBase) && !item2.IsFacility)
				{
					continue;
				}
				item2.SetParentGroup(bool_0: false, group);
				num = 1;
			}
			if (num > 0)
			{
				Client.SelectThisUnit(source.ElementAtOrDefault(0), bool_0: true);
				Client.CurrentMapProfile.ViewMode = MapProfile.MapViewMode.GroupView;
				TSL_Status.Text = "选定的单元已添加到选定的编队";
			}
			break;
		}
		case 0:
			if ((from theAU in list
				select (theAU) into theAU
				where theAU.IsAircraft
				select theAU).Count() == list.Count)
			{
				if (list.Select((ActiveUnit AU) => ((Aircraft)AU).Int32_0).Distinct().Count() > 1 && DarkMessageBox.ShowInformation("There are different types of aircraft in the current selection. Do you want to :" + Environment.NewLine + "-[yes] Enforce a wing with homogenous types of aircrafts, thus splitting it into multiple wings " + Environment.NewLine + "-[No] Force the entire selection into a mixed group ?", "Confirm", DarkDialogButton.YesNo) == DialogResult.Yes)
				{
					Misc.FormIntoGroups(list.ToList(), Client.CurrentScenario, Client.CurrentSide, Misc.GroupingLogic.SplitByType);
				}
				else
				{
					Misc.FormIntoGroups(list.ToList(), Client.CurrentScenario, Client.CurrentSide, Misc.GroupingLogic.MixedGroup);
				}
			}
			else
			{
				Misc.FormIntoGroups(list, Client.CurrentScenario, Client.CurrentSide, Misc.GroupingLogic.MixedGroup, null, bool_0: true);
			}
			Client.CurrentMapProfile.ViewMode = MapProfile.MapViewMode.GroupView;
			TSL_Status.Text = "选定的单元已加入新编队 - 切换到编队视图";
			break;
		}
		list = null;
		Client.MustRefreshMainForm = true;
	}

