			if (TSB_Record.Enabled && SimConfiguration.DefaultGamePreferences.LogDebugInfoToFile)
			{
				GameGeneral.WriteLogDebugInfoToFile("许可证：Command完整版");
			}
			if (SimConfiguration.DefaultGamePreferences.UsePersonalMapProfile)
			{
				Client.CurrentMapProfile = SimConfiguration.DefaultGamePreferences.PersonalMapProfile;
			}
			m_ClientConnection = Client.CurrentMapProfile.RangeSymbol_Colors.AASensor;
			m_DicConnection = Client.CurrentMapProfile.RangeSymbol_Colors.ASSensor;
			_ConsumerConnection = Client.CurrentMapProfile.RangeSymbol_Colors.color_0;
			m_FacadeConnection = Client.CurrentMapProfile.RangeSymbol_Colors.AAWeapon;
			m_ProxyConnection = Client.CurrentMapProfile.RangeSymbol_Colors.ASWeapon;
			readerConnection = Client.CurrentMapProfile.RangeSymbol_Colors.AGWeapon;
			propertyConnection = Client.CurrentMapProfile.RangeSymbol_Colors.color_1;
			importerConnection = Client.CurrentMapProfile.RangeSymbol_Colors.ACRange;
			if (SimConfiguration.DefaultGamePreferences.LogDebugInfoToFile)
			{
				GameGeneral.WriteLogDebugInfoToFile("配置范围颜色");
			}
			if (Client.CurrentMapProfile.RPColor == System.Drawing.Color.Empty)
			{
				Client.CurrentMapProfile.RPColor = System.Drawing.Color.White;
			}
			Client._ValRequest = Client.CurrentMapProfile.RPColor;
			if (Client.CurrentMapProfile.WPColor == System.Drawing.Color.Empty)
			{
				Client.CurrentMapProfile.WPColor = System.Drawing.Color.White;
			}
			Client.m_WrapperRequest = Client.CurrentMapProfile.WPColor;
			if (SimConfiguration.DefaultGamePreferences.LogDebugInfoToFile)
			{
				GameGeneral.WriteLogDebugInfoToFile("Loaded Reference Points Color, Plotted Course and Waypoint Color");
			}
			VisitInterruptibleCollection().Interval = 250;
			VisitInterruptibleCollection().Start();
			if (SimConfiguration.DefaultGamePreferences.LogDebugInfoToFile)
			{
				GameGeneral.WriteLogDebugInfoToFile("完成加载主窗口。");
			}
			InterruptState();
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception exception_ = ex;
			exception_?.Data.Add("Error at 200579", exception_.Message);
			GameGeneral.WriteExceptionsToLog(ref exception_);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

	public void RefreshControlBarCompressionElements()
	{
		GameControlBar gameControlBar = (GameControlBar)ElementHost1.Child;
		TSB_TimeAccel.Enabled = !Client.CurrentScenario.LockFidelityResolution;
		IncreaseCompressionToolStripMenuItem.Enabled = !Client.CurrentScenario.LockFidelityResolution;
		DecreaseCompressionToolStripMenuItem.Enabled = !Client.CurrentScenario.LockFidelityResolution;
		if (Client.CurrentScenario.LockFidelityResolution)
		{
			gameControlBar.TimeComboBox.Visibility = Visibility.Collapsed;
			gameControlBar.PlayButtonAt1Time.Visibility = Visibility.Collapsed;
			gameControlBar.ToggleFidelityMode.Visibility = Visibility.Visible;
		}
		else
		{
			gameControlBar.TimeComboBox.Visibility = Visibility.Visible;
			gameControlBar.PlayButtonAt1Time.Visibility = Visibility.Visible;
			gameControlBar.ToggleFidelityMode.Visibility = Visibility.Collapsed;
		}
		if (Client.CurrentScenario.GameResolution == 0.1f)
		{
			gameControlBar.ToggleFidelityModeLabel.Text = "Fine-grained (0.1)";
		}
		else if (Client.CurrentScenario.GameResolution == 1f)
		{
			gameControlBar.ToggleFidelityModeLabel.Text = "Coarse (1.0)";
		}
		else
		{
			gameControlBar.ToggleFidelityModeLabel.Text = "Very Coarse (5.0)";
		}
	}

	private void CollectState()
	{
		if (!base.Visible)
		{
			return;
		}
		Button1.Text = Conversions.ToString(Client._StateClass);
		RefreshControlBarCompressionElements();
		try
		{
			if (Client.CurrentSide == null)
			{
				if (SimConfiguration.DefaultGamePreferences.ShowGameSpeedButton)
				{
					ButtonGameSpeed.Visible = true;
					ButtonGameSpeed.BackColor = Control.DefaultBackColor;
				}
				else
				{
					ButtonGameSpeed.Visible = false;
				}
			}
			else
			{
				RefreshSetUnitSide();
				TSMI_Lock_UnlockFidelity.Visible = false;
				int num = Client.CurrentSide.SpecialActions.Values.Where((SpecialAction theSA) => theSA.IsActive).Count();
				GameControlBar gameControlBar = (GameControlBar)ElementHost1.Child;
				if (num <= 0)
				{
					gameControlBar.SpecialActionsButton.Visibility = Visibility.Collapsed;
				}
				else
				{
					gameControlBar.SpecialActionsButton.Visibility = Visibility.Visible;
					gameControlBar.SpecialActionLabel.Text = "Special Action";
					gameControlBar.SpecialActionLabel.Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(76, byte.MaxValue, 0));
					if (num > 1)
					{
						gameControlBar.SpecialActionLabel.Text = gameControlBar.SpecialActionLabel.Text.ToString() + "s";
					}
					gameControlBar.SpecialActionLabel.Text = gameControlBar.SpecialActionLabel.Text.ToString() + " (" + num + ")";
				}
				if (Client.SelectedUnit != null && Client.SelectedUnit.IsActiveUnit && ((ActiveUnit)Client.SelectedUnit).IsDestroyed)
				{
					Client.SelectThisUnit(null, bool_0: true);
				}
				List<Module_Unit.Unit> list = new List<Module_Unit.Unit>();
				list.AddRange(Client.CurrentSide.SelectedUnits);
				if (list.Count <= 0)
				{
					if (Client.SelectedUnit != null && Client.SelectedUnit.IsActiveUnit)
					{
						ActiveUnit activeUnit = (ActiveUnit)Client.SelectedUnit;
						if (!activeUnit.IsOperating() && !activeUnit.Navigator.HasFlightPlan)
						{
							Client.SelectThisUnit(null, bool_0: true);
						}
					}
				}
				else
				{
					foreach (Module_Unit.Unit item in list)
					{
						if (item == null)
						{
							continue;
						}
						if (item.IsActiveUnit)
						{
							if (((ActiveUnit)item).IsDestroyed)
							{
								Client.CurrentSide.SelectedUnits_Remove(item);
								if (Client.SelectedUnit == item)
								{
									Client.SelectThisUnit(null, bool_0: true);
								}
							}
						}
						else if (item.DisableWriter() && !Client.CurrentSide.Contacts.Values.Contains((Contact)item) && !Client.CurrentSide.BaseContacts.Values.Contains((Contact)item) && string.IsNullOrEmpty(Client.CurrentMapProfile.String_0))
						{
							Client.CurrentSide.SelectedUnits_Remove(item);
							if (Client.SelectedUnit == item)
							{
								Client.SelectThisUnit(null, bool_0: true);
							}
						}
					}
				}
				if (ItemExporter.ConnectInterruptibleTemplate.repositoryMapping != null && ItemExporter.ConnectInterruptibleTemplate.UnitMessageLog.Visible)
				{
					ItemExporter.ConnectInterruptibleTemplate.UnitMessageLog.RefreshWindow(bool_0: true, bool_1: true);
				}
				GodsEyeViewToolStripMenuItem.Checked = Client.CurrentMapProfile.GodsEye;
				if (!string.IsNullOrEmpty(Client.CurrentMapProfile.String_0) && Client.SelectedUnit == null)
				{
					ToggleIsolatedPOV();
				}
				if (SimConfiguration.DefaultGamePreferences.ShowGameSpeedButton)
				{
					ButtonGameSpeed.Visible = true;
					bool flag = true;
					bool flag2 = true;
					bool flag3 = true;
					Game.GamePreferences defaultGamePreferences = SimConfiguration.DefaultGamePreferences;
					if (defaultGamePreferences.UseAutosave)
					{
						flag3 = false;
					}
					if (Client.CurrentMapProfile.ShowRangeSymbols == MapProfile._ShowElement.All)
					{
						flag2 = false;
					}
					else if (Client.CurrentMapProfile.ShowIlluminationVectors == MapProfile._ShowElement.All)
					{
						flag2 = false;
					}
					else if (Client.CurrentMapProfile.ShowContactEmissions == MapProfile._ShowElement.All)
					{
						flag2 = false;
					}
					if (Client.CurrentMapProfile.ShowNonFriendly)
					{
						flag = false;
					}
					else if (defaultGamePreferences.NavigationMaxDistanceNMSetting == 8f && (double)defaultGamePreferences.NavigationThresholdDistanceDegSetting == 0.5)
					{
						if (defaultGamePreferences.PlacenameVisibility)
						{
							flag = false;
						}
						else if (SimConfiguration.DefaultGamePreferences.ShowMissionArea == Game.GamePreferences.ObjectVisibilitySetting.All)
						{
							flag = false;
						}
						else if (Client.CurrentMapProfile.ShowTargetingVectors == MapProfile._ShowElement.All)
						{
							flag = false;
						}
						else if (Client.CurrentMapProfile.ShowDatalinks == MapProfile._ShowElement.All)
						{
							flag = false;
						}
						else if (defaultGamePreferences.MessageLogCanvas)
						{
							flag = false;
						}
						else if (defaultGamePreferences.ShowGhostedGroupMembers != 0 && defaultGamePreferences.ShowGhostedGroupMembers != Game.GamePreferences.GhostedGroupMembersVisibilitySetting.SelectedUnit)
						{
							if (!defaultGamePreferences.AllowPowerPlanSwitch && RecordThreadBridge.InvokeInterruptibleConnection())
							{
								flag = false;
							}
						}
						else
						{
							flag = false;
						}
					}
					else
					{
						flag = false;
					}
					if (flag)
					{
						if (flag2)
						{
							if (flag3)
							{
								ButtonGameSpeed.BackColor = System.Drawing.Color.LightGreen;
							}
							else
							{
								ButtonGameSpeed.BackColor = System.Drawing.Color.Yellow;
							}
						}
						else
						{
							ButtonGameSpeed.BackColor = System.Drawing.Color.Orange;
						}
					}
					else
					{
						ButtonGameSpeed.BackColor = System.Drawing.Color.Red;
					}
				}
				else
				{
					ButtonGameSpeed.Visible = false;
				}
			}
			if (Client.SelectedUnit == null)
			{
				UnitOrdersToolStripMenuItem.Enabled = false;
				ContactsToolStripMenuItem.Enabled = false;
			}
			else if (Client.CurrentSide.SelectedUnits.Count == 1 && Client.SelectedUnit.IsActiveUnit && Client.SelectedUnit.GetUnitSide() == Client.CurrentSide)
			{
				UnitOrdersToolStripMenuItem.Enabled = Client.SelectedUnit.IsActiveUnit;
				ContactsToolStripMenuItem.Enabled = Client.SelectedUnit.DisableWriter();
			}
			else if (Client.CurrentSide.SelectedUnits.Count > 0)
			{
				UnitOrdersToolStripMenuItem.Enabled = false;
				ContactsToolStripMenuItem.Enabled = false;
				foreach (Module_Unit.Unit selectedUnit in Client.CurrentSide.SelectedUnits)
				{
					if (selectedUnit.IsActiveUnit && selectedUnit.GetUnitSide() == Client.CurrentSide)
					{
						UnitOrdersToolStripMenuItem.Enabled = true;
					}
					else
					{
						ContactsToolStripMenuItem.Enabled = true;
					}
				}
			}
			switch (Client.CurrentGame.Status)
			{
			case Game._GameStatus.Running:
				TSB_StartGame.Checked = true;
				TSB_StartGame.Text = "停止 / 暂停";
				TSB_StartGame.Image = _image_StopPause;
				break;
			case Game._GameStatus.Paused:
				TSB_StartGame.Checked = false;
				TSB_StartGame.Text = "开始/继续";
				TSB_StartGame.Image = _image_StartResume;
				break;
			}
			if (Client.RunToThisTime.HasValue)
			{
				TSL_TimeStepStatus.Visible = true;
				TSL_TimeStepStatus.Text = "自动暂停在" + Misc.UpdateRequest((long)Math.Round((Client.RunToThisTime.Value - Client.CurrentScenario.Time).TotalSeconds)) + " (仿真时间)";
			}
			else
			{
				TSL_TimeStepStatus.Visible = false;
			}
			if (Client.CurrentSide == null)
			{
				TSB_SpecialActions.Visible = false;
				return;
			}
			_ = Client.SelectedUnit;
			SwitchTo_TSMI.Enabled = Client.CurrentScenario.Sides_ReadOnly.Count() > 0;
			if (Client.SelectedUnit == null && Client.theSensorsWindow.Visible)
			{
				Client.theSensorsWindow.Hide();
			}
			if (TrackCamActive)
			{
				if (Client.SelectedUnit == null)
				{
					TrackCamActive = false;
				}
				else
				{
					SetMapCenter(bool_0: true, new GeoPoint(Client.SelectedUnit.GetLongitude(), Client.SelectedUnit.GetLatitude()));
				}
				if (IsAreaSelectingPoint())
				{
					Client.MustRefreshMainForm = true;
				}
			}
			else if (Client.m_CallbackRequest.Count <= 0)
			{
				Client.MustRefreshMainForm = true;
			}
			else
			{
				Client.LoadCustomLayer(Client.m_CallbackRequest.Dequeue());
			}
			if (Client.CurrentSide != null)
			{
				TSB_SpecialActions.Visible = Client.CurrentSide.SpecialActions.Where((KeyValuePair<string, SpecialAction> theKVP) => theKVP.Value.IsActive).Count() > 0;
				if (TSB_SpecialActions.Visible)
				{
					TSB_SpecialActions.Text = "特别动作（" + Conversions.ToString(Client.CurrentSide.SpecialActions.Where((KeyValuePair<string, SpecialAction> theKVP) => theKVP.Value.IsActive).Count()) + ")";
				}
			}
			if (Client.merchantRequest != null)
			{
				DefineManager();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception exception_ = ex;
			exception_?.Data.Add("Error at 200126", exception_.Message);
			GameGeneral.WriteExceptionsToLog(ref exception_);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

