	private void OrderState()
	{
		if (Information.IsNothing(Client.SelectedUnit) || Information.IsNothing(Client.SelectedUnit.GetUnitSide()))
		{
			return;
		}
		try
		{
			if (Client.CurrentUserAction == Client.UserAction.PlottingCourse)
			{
				PlotCourseToolStripMenuItem.Text = "结束规划路径";
			}
			else
			{
				PlotCourseToolStripMenuItem.Text = "规划路径";
			}
			HoldPositionAllUnitsToolStripMenuItem.Enabled = true;
			HoldPositionAllUnitsToolStripMenuItem.Checked = true;
			bool flag = false;
			foreach (ActiveUnit unit in Client.CurrentSide.Units)
			{
				if (unit.IsActiveUnit && unit.GetUnitSide() == Client.CurrentSide && ((unit.IsFacility && !unit.IsFixedFacility) || unit.IsMobileGroundUnit))
				{
					flag = true;
					if (!((Facility)unit).AI.HoldPosition)
					{
						HoldPositionAllUnitsToolStripMenuItem.Checked = false;
						break;
					}
				}
			}
			if (!flag)
			{
				HoldPositionAllUnitsToolStripMenuItem.Checked = false;
				HoldPositionAllUnitsToolStripMenuItem.Enabled = false;
			}
			Doctrine doctrine = null;
			string string_;
			if ((Client.CurrentSide.SelectedUnits.Count == 1 && !Information.IsNothing(Client.SelectedUnit)) || (Client.CurrentSide.SelectedUnits.Count == 0 && !Information.IsNothing(Client.SelectedUnit) && Information.IsNothing(Client.SelectedWaypoint)))
			{
				GroupSelectedUnitsToolStripMenuItem.Enabled = false;
				WeaponsToolStripMenuItem1.Enabled = !Client.SelectedUnit.IsGroup && !Client.SelectedUnit.IsWeapon;
				if (Client.SelectedUnit.GetUnitSide() == Client.CurrentSide)
				{
					if (Client.SelectedUnit.IsWeapon)
					{
						UnassignUnitToolStripMenuItem.Enabled = false;
					}
					else
					{
						UnassignUnitToolStripMenuItem.Enabled = true;
					}
					Side currentSide = Client.CurrentSide;
					Module_Unit.Unit selectedUnit = Client.SelectedUnit;
					string_ = null;
					if (GameGeneral.CanIssueOrdersToThisUnit(currentSide, selectedUnit, bool_1: true, ref string_, Client.CurrentMapProfile.String_0))
					{
						SensorsToolStripMenuItem1.Enabled = true;
					}
					else
					{
						SensorsToolStripMenuItem1.Enabled = false;
					}
					Side currentSide2 = Client.CurrentSide;
					Module_Unit.Unit selectedUnit2 = Client.SelectedUnit;
					string_ = null;
					if (GameGeneral.CanIssueOrdersToThisUnit(currentSide2, selectedUnit2, bool_1: false, ref string_, Client.CurrentMapProfile.String_0))
					{
						PlotCourseToolStripMenuItem.Enabled = true;
						ThrottleAltitudeToolStripMenuItem.Enabled = true;
					}
					else
					{
						PlotCourseToolStripMenuItem.Enabled = false;
						ThrottleAltitudeToolStripMenuItem.Enabled = false;
					}
					if (Client.SelectedUnit.IsActiveUnit && !Client.SelectedUnit.IsWeapon && Client.SelectedUnit.GetUnitSide() == Client.CurrentSide)
					{
						doctrine = ((ActiveUnit)Client.SelectedUnit).Doctrine;
					}
