					{
						if (Client.SelectedUnit.IsWeapon)
						{
							IgnorePlottedCourse_SelectedUnitsToolStripMenuItem1.Enabled = false;
						}
						else
						{
							IgnorePlottedCourse_SelectedUnitsToolStripMenuItem1.Enabled = true;
							Doctrine._UseIgnorePlottedCourse? ignorePlottedCourse = doctrine.GetIgnorePlottedCourse(Client.CurrentScenario, bool_0: false, null, bool_1: false, bool_2: false);
							byte? b;
							if (doctrine.IgnorePlottedCourse_Inherits())
							{
								IgnorePlottedCourse_Selected_Yes.Checked = false;
								IgnorePlottedCourse_Selected_No.Checked = false;
								IgnorePlottedCourse_Selected_Inherit.Checked = true;
							}
							else
							{
								b = (byte?)ignorePlottedCourse;
								if ((b.HasValue ? new bool?(b.GetValueOrDefault() == 1) : null).GetValueOrDefault())
								{
									IgnorePlottedCourse_Selected_Yes.Checked = true;
									IgnorePlottedCourse_Selected_No.Checked = false;
									IgnorePlottedCourse_Selected_Inherit.Checked = false;
								}
								else
								{
									IgnorePlottedCourse_Selected_Yes.Checked = false;
									IgnorePlottedCourse_Selected_No.Checked = true;
									IgnorePlottedCourse_Selected_Inherit.Checked = false;
								}
							}
							Doctrine doctrine12 = doctrine;
							Scenario currentScenario = Client.CurrentScenario;
							bool bool_ = true;
							b = (byte?)doctrine12.GetParentDoctrine(currentScenario, ref bool_).GetIgnorePlottedCourse(Client.CurrentScenario, bool_0: false, null, bool_1: false, bool_2: false);
							if ((b.HasValue ? new bool?(b.GetValueOrDefault() == 1) : null).GetValueOrDefault())
							{
								IgnorePlottedCourse_Selected_Inherit.Text = "继承，是的";
							}
							else
							{
								IgnorePlottedCourse_Selected_Inherit.Text = "继承，不";
							}
						}
						if (Client.SelectedUnit.IsWeapon)
						{
							IgnorePlottedCourse_AllUnitsToolStripMenuItem.Enabled = false;
						}
						else
						{
							int num = 1;
							bool flag12 = true;
							Doctrine._UseIgnorePlottedCourse? useIgnorePlottedCourse = null;
							byte? b23;
							foreach (ActiveUnit unit2 in Client.CurrentSide.Units)
							{
								if (unit2.IsActiveUnit && unit2.GetUnitSide() == Client.CurrentSide)
								{
									if (unit2.IsWeapon)
									{
										continue;
									}
									if (num == 1)
									{
										useIgnorePlottedCourse = (unit2.Doctrine.IgnorePlottedCourse_Inherits() ? null : unit2.Doctrine.GetIgnorePlottedCourse(Client.CurrentScenario, bool_0: false, null, bool_1: false, bool_2: false));
									}
									else if (Information.IsNothing(useIgnorePlottedCourse))
									{
										if (!unit2.Doctrine.IgnorePlottedCourse_Inherits())
										{
											flag12 = false;
											break;
										}
									}
									else
									{
										if (unit2.Doctrine.IgnorePlottedCourse_Inherits())
										{
											flag12 = false;
											break;
										}
										byte? b12 = (byte?)useIgnorePlottedCourse;
										b23 = (byte?)unit2.Doctrine.GetIgnorePlottedCourse(Client.CurrentScenario, bool_0: false, null, bool_1: false, bool_2: false);
										bool? flag23 = ((b12.HasValue & b23.HasValue) ? new bool?(b12.GetValueOrDefault() == b23.GetValueOrDefault()) : null);
										if (((!flag23) ?? flag23).GetValueOrDefault())
										{
											flag12 = false;
											break;
										}
									}
								}
								num++;
							}
							IgnorePlottedCourse_AllUnitsToolStripMenuItem.Enabled = true;
							if (flag12)
							{
								if (Information.IsNothing(useIgnorePlottedCourse))
								{
									IgnorePlottedCourse_All_Yes.Checked = false;
									IgnorePlottedCourse_All_No.Checked = false;
									IgnorePlottedCourse_All_Inherit.Checked = true;
								}
								else
								{
									b23 = (byte?)useIgnorePlottedCourse;
									if ((b23.HasValue ? new bool?(b23.GetValueOrDefault() == 1) : null).GetValueOrDefault())
									{
										IgnorePlottedCourse_All_Yes.Checked = true;
										IgnorePlottedCourse_All_No.Checked = false;
										IgnorePlottedCourse_All_Inherit.Checked = false;
									}
									else
									{
										IgnorePlottedCourse_All_Yes.Checked = false;
										IgnorePlottedCourse_All_No.Checked = true;
										IgnorePlottedCourse_All_Inherit.Checked = false;
									}
								}
							}
							else
							{
								IgnorePlottedCourse_All_Yes.Checked = false;
								IgnorePlottedCourse_All_No.Checked = false;
