	public void DrawElevationIntervals(Graphics graphics_0)
	{
		try
		{
			System.Drawing.Pen pen = new System.Drawing.Pen(System.Drawing.Brushes.Red, 1f);
			double num = -90.0;
			do
			{
				num = Conversions.ToDouble(string.Format("{0:0.0}", num, 2));
				double num2 = -180.0;
				do
				{
					num2 = Conversions.ToDouble(string.Format("{0:0.0}", num2, 2));
					if (ManagerListenerManager.CreateInterruptibleMap(WorldWindow1, num, num2))
					{
						try
						{
							ManagerListenerManager.InstantiateInterruptibleMap(WorldWindow1, InterpreterObjectListener._UtilsResolver, ref num, ref num2, ref _DescriptorConnection, ref poolConnection);
							graphics_0.DrawLine(pen, _DescriptorConnection - 4, poolConnection - 4, _DescriptorConnection + 4, poolConnection + 4);
							graphics_0.DrawLine(pen, _DescriptorConnection - 4, poolConnection + 4, _DescriptorConnection + 4, poolConnection - 4);
						}
						catch (Exception ex)
						{
							ProjectData.SetProjectError(ex);
