	private void ConcatAuthentication(object sender, EventArgs e)
	{
		if (Client.CurrentScenario == null || SimConfiguration.DefaultGamePreferences == null)
		{
			return;
		}
		FillProducer().Interval = 100;
		if (Client.CurrentScenario.UsesHighFidelity())
		{
			CalcGetter().Interval = 100;
			CheckProducer().Interval = 250;
			Client.CloneScenarioInterval = 10;
		}
		else
		{
			CalcGetter().Interval = 50;
			CheckProducer().Interval = 500;
			Client.CloneScenarioInterval = 30;
		}
		if (Client.CurrentGame.Status == Game._GameStatus.Running)
		{
			Client.AutosaveCountdown -= CalcGetter().Interval;
		}
		if (Client.CurrentScenario.ExecutionInProgress)
		{
			return;
		}
		if (Client.RunToThisTime.HasValue)
		{
			if (DateTime.Compare(Client.CurrentScenario.Time, Client.RunToThisTime.Value) < 0)
			{
				Client.ProcessNewTurn(CalcGetter().Interval);
				Client.MustRefreshMainForm = true;
			}
			else
			{
				Client.CurrentGame.Pause();
				Client.RunToThisTime = null;
				CollectState();
			}
		}
		else if (Client.CurrentScenario.TimeToHalt.HasValue)
		{
			if (DateTime.Compare(Client.CurrentScenario.Time, Client.CurrentScenario.TimeToHalt.Value) < 0)
			{
				Client.ProcessNewTurn(CalcGetter().Interval);
				Client.MustRefreshMainForm = true;
			}
			else
			{
				Client.CurrentGame.Pause();
				Client.CurrentScenario.TimeToHalt = null;
				CollectState();
			}
		}
		else
		{
			Client.ProcessNewTurn(CalcGetter().Interval);
			Client.MustRefreshMainForm = true;
		}
	}

	private void InterruptAuthentication(object sender, EventArgs e)
	{
		ToolStripMenuItem toolStripMenuItem = sender as ToolStripMenuItem;
		Side[] sides_ReadOnly = Client.CurrentScenario.Sides_ReadOnly;
		int num = 0;
		Side side;
		while (true)
		{
			if (num < sides_ReadOnly.Length)
			{
				side = sides_ReadOnly[num];
				if (Operators.CompareString(side.Name, toolStripMenuItem.Text, TextCompare: true) == 0)
				{
					break;
				}
				num++;
				continue;
			}
			return;
		}
		Client.CurrentScenario.SetCurrentSide(side);
	}

