	private ReferencePoint InstantiateAuthentication()
	{
		HashSet<ReferencePoint> hashSet = new HashSet<ReferencePoint>();
		if (Client.CurrentSide == null)
		{
			return null;
		}
		short num = (short)(MapClickDrawPoint.Y - 4);
		short num2 = (short)(MapClickDrawPoint.Y + 4);
		short num3 = (short)(MapClickDrawPoint.X - 4);
		short num4 = (short)(MapClickDrawPoint.X + 4);
		List<ReferencePoint> list = new List<ReferencePoint>();
		list.AddRange(Client.CurrentSide.RefPoints);
		foreach (ReferencePoint item in list)
		{
			if (!Information.IsNothing(item))
			{
				System.Drawing.Point point = ManagerListenerManager.SetInterruptibleMap(WorldWindow1, item.Latitude, item.Longitude);
				if (num <= point.Y && point.Y <= num2 && num3 <= point.X && point.X <= num4)
				{
					hashSet.Add(item);
				}
			}
		}
		return hashSet.OrderBy((ReferencePoint referencePoint_0) => referencePoint_0.RangeToPoint_Horiz(mapperCode.Longitude, mapperCode.Latitude)).ElementAtOrDefault(0);
	}

