		}
		if (m_QueueConnection.TotalSeconds <= 0.0)
		{
			_ItemConnection = string.Empty;
		}
		else
		{
			_RegConnection.Clear();
			_RegConnection.Append(Misc.UpdateRequest((long)Math.Round(m_QueueConnection.TotalSeconds))).Append(" 剩余 - ");
			_ItemConnection = _RegConnection.ToString();
		}
		if (!double.IsNaN(GetMapCenter().Longitude) && !double.IsNaN(GetMapCenter().Latitude))
		{
			_RegConnection.Clear();
			_RegConnection.Append(" - 当地：").Append(Misc.DisableRequest(Client.CurrentScenario.Time, GetMapCenter().Longitude, Client.CurrentScenario.Use_DST, Client.CurrentScenario.DST_Start, Client.CurrentScenario.DST_End).Hour.ToString("D2")).Append(":")
				.Append(m_TagConnection)
				.Append(":")
				.Append(fieldConnection);
			m_SetterConnection = _RegConnection.ToString();
		}
		else
		{
			m_SetterConnection = string.Empty;
		}
		CultureInfo currentCulture = Thread.CurrentThread.CurrentCulture;
		Thread.CurrentThread.CurrentCulture = templateConnection;
		string value = Client.CurrentScenario.Time.ToLongDateString();
		Thread.CurrentThread.CurrentCulture = currentCulture;
		_RegConnection.Clear();
		_RegConnection.Append("时间：").Append(value).Append(" - 祖鲁：")
			.Append(mockConnection)
			.Append(":")
			.Append(m_TagConnection)
			.Append(":")
			.Append(fieldConnection)
			.Append(m_SetterConnection)
			.Append(" - ")
			.Append(_ItemConnection)
			.Append(" Camera: ");
		_RegConnection.Append((long)CameraAltitude).Append("米 ").Append(mappingConnection);
		if (SimConfiguration.DefaultGamePreferences.ShowDiagnostics)
		{
			if (Client.CurrentGame.Status == Game._GameStatus.Paused)
			{
				Client.iteratorClass = Client.CurrentScenario.ActiveUnits_List.Count;
				Client._RoleClass = Pathfinding.InterruptStub();
				Client.m_FactoryClass = Pathfinding.RemoveStub();
			}
			_PrototypeConnection.Clear();
			_PrototypeConnection.Append(" GPU: ");
			_PrototypeConnection.Append(Main.Instance?.AdapterDescription);
			_PrototypeConnection.Append(" - 单元数量：").Append(Client.iteratorClass.ToString());
			_PrototypeConnection.Append(" - 脉冲时间：").Append(Client.initializerClass.ToString()).Append("ms");
			if (Client._RoleClass > 0.0 || Client.m_FactoryClass != null)
			{
				_PrototypeConnection.Append(" - 路径规划队列：").Append(Client._RoleClass.ToString());
				_PrototypeConnection.Append("当前：");
				if (Client.m_FactoryClass == null)
				{
					_PrototypeConnection.Append("None");
				}
				else
				{
					_PrototypeConnection.Append(Client.m_FactoryClass);
				}
			}
			_RegConnection.Append(_PrototypeConnection.ToString());
			if (Exporter_General.EventExporters_Interactive.Where((IEventExporter theExp) => theExp.ExporterType != IEventExporter.EventExporterType.TacviewPipe).Count() <= 0)
			{
				StatusCaptionLine2Visible = false;
			}
			else
			{
				_ComparatorConnection.Clear();
				_ComparatorConnection.Append("事件队列长度：");
				foreach (IEventExporter item in Exporter_General.EventExporters_Interactive)
				{
					if (item.ExporterType != IEventExporter.EventExporterType.TacviewPipe)
					{
						_ComparatorConnection.Append(" ").Append(item.Name).Append(":")
							.Append(item.QueueLength);
					}
				}
				StatusCaptionLine2 = _ComparatorConnection.ToString();
				StatusCaptionLine2Visible = true;
			}
		}
		StatusCaptionLine1 = _RegConnection.ToString();
		StatusCaptionLine1Visible = true;
	}

