	private void ListAuthentication(object sender, DoWorkEventArgs e)
	{
		Geopoint_Struct geopoint_Struct = ManagerListenerManager.CalculateInterruptibleMap(WorldWindow1, CurrentMousePosition.X, CurrentMousePosition.Y);
		if (geopoint_Struct.Latitude <= 90.0 && geopoint_Struct.Latitude >= -90.0 && geopoint_Struct.Longitude <= 180.0 && geopoint_Struct.Longitude >= -180.0)
		{
			int elevation = Terrain.GetElevation(geopoint_Struct.Latitude, geopoint_Struct.Longitude, bool_0: true, Client.CurrentScenario);
			if (SimConfiguration.DefaultGamePreferences.ShowAltitudeInFeet)
			{
				if (elevation <= 0)
				{
					_CallbackConnection = " - 深度：" + Conversions.ToString((int)Math.Round((float)elevation * 3.28084f)) + "英尺 ";
				}
				else
				{
					_CallbackConnection = " - 海拔：" + Conversions.ToString((int)Math.Round((float)elevation * 3.28084f)) + "英尺 ";
				}
			}
			else if (elevation <= 0)
			{
				_CallbackConnection = " - 深度：" + Conversions.ToString(elevation) + "米 ";
			}
			else
			{
				_CallbackConnection = " - 海拔：" + Conversions.ToString(elevation) + "米 ";
			}
			if (elevation < 0)
			{
				int int_ = 0;
				int int_2 = 0;
				float float_ = 0f;
				SonarModel.GetThermalLayerAtThisLocation(geopoint_Struct.Latitude, geopoint_Struct.Longitude, elevation, ref int_, ref int_2, ref float_, bool_0: true, Client.CurrentScenario);
				if (float_ == 0f)
				{
					_DecoratorConnection = "No Layer";
				}
				else if (SimConfiguration.DefaultGamePreferences.ShowAltitudeInFeet)
				{
					_DecoratorConnection = "温跃层：" + Conversions.ToString((int)Math.Round((float)int_ * 3.28084f)) + "英尺到" + Conversions.ToString((int)Math.Round((float)int_2 * 3.28084f)) + "英尺 - 强度：" + string.Format("{0:0.00}", float_, 2);
				}
				else
				{
					_DecoratorConnection = "温跃层：" + Conversions.ToString(int_) + "米到" + Conversions.ToString(int_2) + "米 - 强度：" + string.Format("{0:0.00}", float_, 2);
				}
				int num = SonarModel.ConnectSpecification(geopoint_Struct.Latitude);
				int num2 = (int)Math.Round(SonarModel.smethod_0(geopoint_Struct.Latitude, geopoint_Struct.Longitude, Client.CurrentSide, Client.CurrentScenario));
				string text = ((elevation >= num || num2 <= 0) ? " - 无 汇聚区" : (" - 汇聚区 " + Conversions.ToString(num2) + "-" + Conversions.ToString(2 * num2) + "-" + Conversions.ToString(3 * num2) + "-" + Conversions.ToString(4 * num2) + "海里 "));
				_DecoratorConnection += text;
				if (elevation > -415)
				{
					_ThreadConnection = LandCover.LogoutClass(LandCover.AddClass(geopoint_Struct.Latitude, geopoint_Struct.Longitude, Client.CurrentScenario, (List<CustomEnvironmentZone>)(object)Client.CurrentScenario.GetNatureSide()).theTerrainType);
					if (_ThreadConnection.Contains("Water"))
					{
						_ThreadConnection = string.Empty;
					}
					else
					{
						_DecoratorConnection = string.Empty;
					}
				}
				return;
			}
			_ProcessConnection = "坡度：" + Conversions.ToString((int)Math.Round(100f * Terrain.InvokeWatcher(geopoint_Struct.Latitude, geopoint_Struct.Longitude, bool_0: true, Client.CurrentScenario))) + "% ";
			if (Client.CurrentScenario.DeclaredFeatures.Contains(Scenario.ScenarioFeatureOption.LandTypeEffects))
			{
				Side natureSide = Client.CurrentScenario.GetNatureSide();
				(LandCover.LandCoverType, int) tuple = LandCover.AddClass(geopoint_Struct.Latitude, geopoint_Struct.Longitude, Client.CurrentScenario, (List<CustomEnvironmentZone>)(object)natureSide);
				_ThreadConnection = LandCover.LogoutClass(tuple.Item1);
				if (tuple.Item2 > 1)
				{
					if (SimConfiguration.DefaultGamePreferences.ShowAltitudeInFeet)
					{
						int num3 = (int)Math.Round((float)elevation * 3.28084f);
						int num4 = (int)Math.Round((float)tuple.Item2 * 3.28084f);
						_ThreadConnection = _ThreadConnection + "(Height: " + num4 + "ft, Skyline: ";
						_ThreadConnection = _ThreadConnection + (num4 + num3) + "ft)";
					}
					else
					{
						_ThreadConnection = _ThreadConnection + "(Height: " + tuple.Item2 + "m, Skyline: ";
						_ThreadConnection = _ThreadConnection + (tuple.Item2 + elevation) + "m)";
					}
				}
			}
			else
			{
				_ThreadConnection = LandCover.LogoutClass(LandCover.DestroyClass(geopoint_Struct.Latitude, geopoint_Struct.Longitude, Client.CurrentScenario));
			}
			_DecoratorConnection = string.Empty;
		}
		else
		{
			_CallbackConnection = "";
		}
	}

	private void ResolveAuthentication()
	{
		try
		{
			if (Information.IsNothing(WorldWindow1))
			{
				GameGeneral.WriteLogDebugInfoToFile("找不到WorldWindow1对象！错误200596");
				return;
			}
			WorldWindow worldWindow = WorldWindow1;
			ref System.Drawing.Point currentMousePosition = ref CurrentMousePosition;
			int int_ = currentMousePosition.X;
			ref System.Drawing.Point currentMousePosition2 = ref CurrentMousePosition;
			int int_2 = currentMousePosition2.Y;
			double double_ = 0.0;
			double double_2 = 0.0;
			ManagerListenerManager.PopInterruptibleMap(worldWindow, ref int_, ref int_2, ref double_, ref double_2);
			currentMousePosition2.Y = int_2;
			currentMousePosition.X = int_;
			if (double.IsNaN(double_) || double.IsNaN(double_2))
			{
				return;
			}
			DateTime time = Client.CurrentScenario.Time;
			bool use_DST = Client.CurrentScenario.Use_DST;
			string dST_Start = Client.CurrentScenario.DST_Start;
			string dST_End = Client.CurrentScenario.DST_End;
			string text = Misc.DisableRequest(time, double_, use_DST, dST_Start, dST_End).ToString("HH:mm:ss");
			Weather.TTimeOfDayType tTimeOfDayType = SunModule.CollectSpecification(Client.CurrentScenario, time.Year, time.Month, time.Day, time.Hour, time.Minute, time.Second, bool_0: true, double_2, double_, 0.0);
			string text2 = "(" + SunModule.ForgotSpecification(tTimeOfDayType, time, double_, use_DST, dST_Start, dST_End) + ")";
			switch (tTimeOfDayType)
			{
			case Weather.TTimeOfDayType.tod_Day:
				text2 = "（白天）";
				break;
			case Weather.TTimeOfDayType.tod_Twilight:
				text2 = ((Misc.DisableRequest(time, double_, use_DST, dST_Start, dST_End).Hour < 12) ? "（黎明）" : "（黄昏）");
				break;
			case Weather.TTimeOfDayType.tod_Night:
				text2 = "（夜晚）";
				break;
			}
			string text3 = "天气：";
			Weather.WeatherProfile weatherAtThisTimeAndPlace = Weather.GetWeatherAtThisTimeAndPlace(Client.CurrentScenario, double_2, double_, 0);
			text3 = text3 + weatherAtThisTimeAndPlace.CloudInfo_Description + " - " + weatherAtThisTimeAndPlace.RainfallRate_Description + " - " + Conversions.ToString((int)weatherAtThisTimeAndPlace.GetActualTemp(tTimeOfDayType)) + "°C - 风力/海况 " + Conversions.ToString(weatherAtThisTimeAndPlace.SeaState);
			string text4 = "";
			if (Client.SelectedUnit != null)
			{
				float num = Math2.VerifyClass(Client.SelectedUnit.GetLatitude(), Client.SelectedUnit.GetLongitude(), double_2, double_);
				text4 = ((num < 1f) ? (" - " + Conversions.ToString((int)Math.Round(num * 1852f)) + "米距离所选") : ((num < 10f) ? (" - " + $"{num:0.00}" + "海里距离所选") : (" - " + $"{num:0}" + "海里距离所选")));
			}
			Game.GamePreferences.MapCursorBoxVisibilitySetting mapCursorBox = SimConfiguration.DefaultGamePreferences.MapCursorBox;
			if ((int)mapCursorBox <= 1)
			{
				DataCursorMouseX = CurrentMousePosition.X;
				DataCursorMouseY = CurrentMousePosition.Y;
				DataCursorLine1 = Misc.CoordinateToString(double_2, double_, SimConfiguration.DefaultGamePreferences.GeoCoordinateType) + text4 + _CallbackConnection + " ";
				if (string.IsNullOrEmpty(_DecoratorConnection))
				{
					DataCursorLine2 = _ProcessConnection + " - " + _ThreadConnection + " ";
				}
				else
				{
					DataCursorLine2 = _DecoratorConnection + " ";
				}
				DataCursorLine3 = "当地时间：" + text + " " + text2 + " ";
				DataCursorLine4 = text3 + " ";
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception exception_ = ex;
			exception_?.Data.Add("Error at 200601", exception_.Message);
			GameGeneral.WriteExceptionsToLog(ref exception_);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

	private void PostAuthentication(object sender, EventArgs e)
	{
		try
		{
			if (Operators.CompareString(Client.FloatingLicenseErrorMessage, string.Empty, TextCompare: true) == 0)
			{
				if (Client.CurrentScenario.UnhandledPopUpMessages.Count > 0)
				{
					RunAuthentication();
				}
				if (Client.MustRefreshMainForm || Client.CurrentGame.Status == Game._GameStatus.Running)
				{
					CollectState();
					Client.MustRefreshMainForm = false;
				}
				InitState();
				UpdateAccount();
			}
			else
			{
				if (Client.CurrentGame.Status == Game._GameStatus.Running)
				{
					Client.CurrentGame.Pause();
				}
				if (Client.CurrentGame.GameMode != Game._GameMode.MonteCarlo)
				{
					Client._WatcherRequest.ScenarioToSave = Client.CurrentScenario;
				}
				Client._WatcherRequest.ErrorReason = Client.FloatingLicenseErrorMessage;
				Client._WatcherRequest.Show();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception exception_ = ex;
			exception_?.Data.Add("Error at 200201", exception_.Message);
			GameGeneral.WriteExceptionsToLog(ref exception_);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

	private void RunAuthentication()
	{
		while (Client.CurrentScenario.UnhandledPopUpMessages.Count > 0)
		{
			LoggedMessage loggedMessage = Client.CurrentScenario.UnhandledPopUpMessages.Dequeue();
			if (!Information.IsNothing(Client.CurrentSide) && (loggedMessage.Side == Client.CurrentSide || loggedMessage.Side == null))
			{
				NewMessageForm value = null;
				Client.OpenMessageWindows.TryGetValue(loggedMessage.Type, out value);
				if (Information.IsNothing(value))
				{
					value = new NewMessageForm();
					Client.OpenMessageWindows.Add(loggedMessage.Type, value);
				}
				value.Messages.Add(loggedMessage);
			}
		}
		if (Client.CurrentGame.Status == Game._GameStatus.Running && Client.OpenMessageWindows.Values.Count > 0)
		{
			Client.CurrentGame.Pause();
		}
		bool flag = false;
		foreach (NewMessageForm value2 in Client.OpenMessageWindows.Values)
		{
			value2.Show();
			flag = true;
		}
		if (flag && Client.CurrentGame.Status == Game._GameStatus.Paused)
		{
			RightColumn1.RefreshPanels(Client.CurrentScenario, Client.CurrentSide, Client.SelectedUnit, bool_0: false);
		}
	}

