	private void SortAuthentication()
	{
		issuerConnection = new CommandLayer("CommandLayer", LogoutState);
		issuerConnection.Initialize(WorldWindow1.DrawArgs);
		WorldWindow1.CommandLayer = issuerConnection;
		try
		{
			if (SimConfiguration.DefaultGamePreferences.LogDebugInfoToFile)
			{
				GameGeneral.WriteLogDebugInfoToFile("准备Wold窗口。");
			}
			if (SimConfiguration.DefaultGamePreferences.LogDebugInfoToFile && !Directory.Exists(Path.Combine(GameGeneral.WWFolderPath, "Cache")))
			{
				GameGeneral.WriteLogDebugInfoToFile("准备Wold Window失败了！找不到路径" + Path.Combine(GameGeneral.WWFolderPath, "Cache"));
			}
			if (SimConfiguration.DefaultGamePreferences.StartFullScreen)
			{
				Slide_RC_In();
			}
			m_MapperRef.PositionCorrectlyWithinMainform(this);
			BMNGLayerToolStripMenuItem.Checked = true;
			PlacenamesToolStripMenuItem.Checked = true;
			TSMI_Sentinel2.Checked = true;
			BordersCoastlinesToolStripMenuItem.Checked = true;
			DayNightLightingToolStripMenuItem.Checked = Client.CurrentMapProfile.DayNightLighting;
			WorldWindow1.DrawArgs.WorldCamera.PanEvent += CalcAuthentication;
			if (SimConfiguration.DefaultGamePreferences.LogDebugInfoToFile)
			{
				GameGeneral.WriteLogDebugInfoToFile("准备完成Wold窗口。");
			}
			HandleMapProfileSettingsChange();
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception exception_ = ex;
			exception_?.Data.Add("Error at 200519", exception_.Message);
			GameGeneral.WriteExceptionsToLog(ref exception_);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

