	private void IncludeParams(object sender, EventArgs e)
	{
		PrintProc().Multiselect = true;
		if (PrintProc().ShowDialog() != DialogResult.OK)
		{
			return;
		}
		List<string> list = new List<string>();
		List<string> list2 = new List<string>();
		string[] fileNames = PrintProc().FileNames;
		for (int i = 0; i < fileNames.Length; i = checked(i + 1))
		{
			string text = fileNames[i];
			try
			{
				string text2 = ScenContainer.LoadFromFile(text).GetScenarioObject_AsXML();
				text = Strings.Replace(text, ".scen", "", 1, -1, CompareMethod.Text);
				text = Strings.Replace(text, ".save", "", 1, -1, CompareMethod.Text);
				text = Strings.Replace(text, ".xml", "", 1, -1, CompareMethod.Text);
				try
				{
					text2 = Misc.CleanUpXML_Headers(text2);
					XmlDocument xmlDocument = new XmlDocument();
					xmlDocument.LoadXml(text2);
					xmlDocument.Save(new XmlTextWriter(text + ".xml", Encoding.UTF8)
					{
						Formatting = Formatting.Indented
					});
				}
				catch (Exception projectError)
				{
					ProjectData.SetProjectError(projectError);
					File.WriteAllText(text + ".xml", text2);
					ProjectData.ClearProjectError();
				}
				list.Add(text);
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				list2.Add(text);
				Interaction.MsgBox("Error while exporting scenario: " + text + " . Error message:" + ex2.Message);
				ProjectData.ClearProjectError();
			}
		}
		string text3 = null;
		if (list.Count > 0)
		{
			text3 += "The following scenarios were exported to XML successfully: ";
			foreach (string item in list)
			{
				text3 = text3 + "\r\n" + item;
			}
			text3 += "\r\n";
		}
		if (list2.Count > 0)
		{
			text3 += "The following scenarios were NOT exported to XML due to errors: ";
			foreach (string item2 in list2)
			{
				text3 = text3 + "\r\n" + item2;
			}
			text3 += "\r\n";
		}
		Interaction.MsgBox(text3);
		if (list.Count > 0)
		{
			text3 += "The following scenarios were exported to XML successfully: ";
			foreach (string item3 in list)
			{
				text3 = text3 + "\r\n" + item3;
			}
			text3 += "\r\n";
		}
		if (list2.Count > 0)
		{
			text3 += "The following scenarios were NOT exported to XML due to errors: ";
			foreach (string item4 in list2)
			{
				text3 = text3 + "\r\n" + item4;
			}
			text3 += "\r\n";
		}
		Interaction.MsgBox(text3);
	}

