	public void HandleMapProfileSettingsChange()
	{
		if (!((WorldWindow1 == null) | (Main.Instance == null)))
		{
			MapProfile currentMapProfile = Client.CurrentMapProfile;
			if (Client.CurrentGame.GameMode != Game._GameMode.ScenEdit)
			{
				currentMapProfile.GodsEye = false;
			}
			AirSensorsToolStripMenuItem.Checked = currentMapProfile.RangeSymbol_AASensor != MapProfile._ShowElement.DontShow;
			AirWeaponsToolStripMenuItem.Checked = currentMapProfile.RangeSymbol_AAWeapon != MapProfile._ShowElement.DontShow;
			SurfaceSensorsToolStripMenuItem.Checked = currentMapProfile.RangeSymbol_ASSensor != MapProfile._ShowElement.DontShow;
			SurfaceWeaponsToolStripMenuItem.Checked = currentMapProfile.RangeSymbol_ASWeapon != MapProfile._ShowElement.DontShow;
			LandWeaponsToolStripMenuItem.Checked = currentMapProfile.RangeSymbol_AGWeapon != MapProfile._ShowElement.DontShow;
			UnderwaterSensorsToolStripMenuItem.Checked = currentMapProfile.RangeSymbol_ASWSensor != MapProfile._ShowElement.DontShow;
			UnderwaterWeaponsToolStripMenuItem.Checked = currentMapProfile.RangeSymbol_ASWWeapon != MapProfile._ShowElement.DontShow;
			TSMI_AircraftRange.Checked = currentMapProfile.RangeSymbol_ACRange != MapProfile._ShowElement.DontShow;
			MergeRangesymbolsToolStripMenuItem.Checked = currentMapProfile.MergeRangeSymbols;
			ShowNonfriendlyToolStripMenuItem.Checked = currentMapProfile.ShowNonFriendly;
			VirtualEarthTSMI.Checked = currentMapProfile.Layer_VirtualEarth;
			MapLatLonGridToolStripMenuItem.Checked = currentMapProfile.ShowLatLonGrid;
			TSMI_BaseEarthLayer.Checked = currentMapProfile.ShowBaseEarth;
			BMNGLayerToolStripMenuItem.Checked = currentMapProfile.Layer_BMNG;
			TSMI_Sentinel2.Checked = currentMapProfile.Layer_Sentinel2;
			ReliefLayerToolStripMenuItem.Checked = currentMapProfile.Layer_Relief;
			TSMI_StamenTerrain.Checked = currentMapProfile.Layer_StamenTerrain;
			TSMI_StamenRoads.Checked = currentMapProfile.Layer_StamenRoads;
			BordersCoastlinesToolStripMenuItem.Checked = currentMapProfile.Layer_Borders;
			PlacenamesToolStripMenuItem.Checked = currentMapProfile.Layer_Placenames;
			TSMI_LandCover.Checked = currentMapProfile.Layer_LandCover;
			TSMI_OpenTopoMap.Checked = currentMapProfile.Layer_OpenTopoMap;
			DayNightLightingToolStripMenuItem.Checked = currentMapProfile.DayNightLighting;
			switch (currentMapProfile.ShowDatalinks)
			{
			case MapProfile._ShowElement.All:
				TSMI10.Checked = false;
				TSMI11.Checked = true;
				TSMI12.Checked = false;
				break;
			case MapProfile._ShowElement.SelectedUnit:
				TSMI10.Checked = true;
				TSMI11.Checked = false;
				TSMI12.Checked = false;
				break;
			case MapProfile._ShowElement.DontShow:
				TSMI10.Checked = false;
				TSMI11.Checked = false;
				TSMI12.Checked = true;
				break;
			}
			switch (currentMapProfile.ShowDatablocks)
			{
			case MapProfile._ShowElement.All:
				TSMI7.Checked = false;
				TSMI8.Checked = true;
				TSMI9.Checked = false;
				break;
			case MapProfile._ShowElement.SelectedUnit:
				TSMI7.Checked = true;
				TSMI8.Checked = false;
				TSMI9.Checked = false;
				break;
			case MapProfile._ShowElement.DontShow:
				TSMI7.Checked = false;
