	public void ShowDoctrineROE(ScenarioObject scenarioObject_0, ref ReadOnlyCollection<Module_Unit.Unit> readOnlyCollection_0, ref List<ActiveUnit> list_0, bool bool_0)
	{
		DoctrineForm doctrineForm = new DoctrineForm();
		doctrineForm.UnitIsOperating = bool_0;
		doctrineForm.RefreshSelectedUnits(scenarioObject_0, ref readOnlyCollection_0, ref list_0);
		if (Information.IsNothing(doctrineForm.Subject) && (Information.IsNothing(doctrineForm.SelectedUnits) || doctrineForm.SelectedUnits.Count == 0) && !Information.IsNothing(scenarioObject_0) && (object)scenarioObject_0.GetType() != typeof(Side))
		{
			return;
		}
		if (!Information.IsNothing(doctrineForm.Subject))
		{
			if ((object)doctrineForm.Subject.GetType() == typeof(Group))
			{
				Group group = (Group)doctrineForm.Subject;
				if (Information.IsNothing(group.GroupLead))
				{
					doctrineForm.isEscorts = false;
				}
				else
				{
					doctrineForm.isEscorts = group.GroupLead.AI.IsEscort;
				}
			}
			else if ((object)doctrineForm.Subject.GetType() == typeof(ActiveUnit))
			{
				doctrineForm.isEscorts = ((ActiveUnit)doctrineForm.Subject).AI.IsEscort;
			}
		}
		if (Information.IsNothing(doctrineForm.Subject))
		{
			doctrineForm.Subject = Client.CurrentSide;
		}
		doctrineForm.Show();
	}

