	public void DBMenu_Build()
	{
		TSMI_CurrentDB.Text = "当前：" + Client.CurrentDB.DBName;
		DBRecord dBRecord = (from theDBR in DBOps.RegisteredDBs()
			where theDBR.DBID == 1 && theDBR.LocalCopyExists
			select theDBR).FirstOrDefault();
		if (Information.IsNothing(dBRecord))
		{
			TSMI_UseLatestDB3000.Visible = false;
		}
		else
		{
			TSMI_UseLatestDB3000.Visible = true;
			TSMI_UseLatestDB3000.Text = "使用最新的 DB3000: " + dBRecord.DBName;
			TSMI_UseLatestDB3000.Tag = dBRecord.Hash;
		}
		DBRecord dBRecord2 = (from theDBR in DBOps.RegisteredDBs()
			where theDBR.DBID == 2 && theDBR.LocalCopyExists
			select theDBR).FirstOrDefault();
		if (Information.IsNothing(dBRecord2))
		{
			TSMI_UseLatestCWDB.Visible = false;
		}
		else
		{
			TSMI_UseLatestCWDB.Visible = true;
			TSMI_UseLatestCWDB.Text = "使用最新的 CWDB: " + dBRecord2.DBName;
			TSMI_UseLatestCWDB.Tag = dBRecord2.Hash;
		}
		m_ConfigConnection = true;
	}

	public void AdjustQuickJumpMenu()
	{
		QuickJumpTSMI.DropDownItems.Clear();
		if (!Information.IsNothing(Client.CurrentSide))
		{
			IOrderedEnumerable<KeyValuePair<int, QuickJumpSlot>> orderedEnumerable = Client.CurrentSide.QuickJumpSlots.OrderBy((KeyValuePair<int, QuickJumpSlot> theKVP) => theKVP.Key);
			Contact contact = null;
			ActiveUnit activeUnit = null;
			foreach (KeyValuePair<int, QuickJumpSlot> item in orderedEnumerable)
			{
				QuickJumpSlot value = item.Value;
				string text = "";
				string left = value.LocationString.Split('_')[0];
				if (Operators.CompareString(left, "AU", TextCompare: true) == 0)
				{
					Client.CurrentScenario.ActiveUnits.TryGetValue(value.LocationString.Split('_')[1], ref activeUnit);
					text = (Information.IsNothing(activeUnit) ? "单元：[不再有效]" : ("单元：" + activeUnit.Name));
				}
				else if (Operators.CompareString(left, "Con", TextCompare: true) == 0)
				{
					Client.CurrentSide.Contacts.TryGetValue(value.LocationString.Split('_')[1], ref contact);
					text = (Information.IsNothing(contact) ? "目标：[不再有效]" : ("目标：" + contact.Name));
				}
				ToolStripMenuItem obj = (ToolStripMenuItem)QuickJumpTSMI.DropDownItems.Add(text, null, DisableParams);
				obj.Tag = value;
				obj.ShortcutKeyDisplayString = value.Index.ToString();
			}
		}
		QuickJumpTSMI.Enabled = QuickJumpTSMI.DropDownItems.Count > 0;
	}

