	public void HandleTimeCompressionChanged()
	{
		try
		{
			switch (Client.CurrentScenario.TimeCompression_SimSeconds)
			{
			case 15:
				TSB_TimeAccel.Text = "加速比: 15x";
				m_ConfigCode.TimeComboBox.SelectedIndex = 3;
				break;
			case 1:
				TSB_TimeAccel.Text = "加速比：1";
				m_ConfigCode.TimeComboBox.SelectedIndex = 0;
				break;
			case 2:
				TSB_TimeAccel.Text = "加速比：2x";
				m_ConfigCode.TimeComboBox.SelectedIndex = 1;
				break;
			case 5:
				TSB_TimeAccel.Text = "加速比：5x";
				m_ConfigCode.TimeComboBox.SelectedIndex = 2;
				break;
			case 150:
				TSB_TimeAccel.Text = "Time Acceleration: Super Turbo";
				m_ConfigCode.TimeComboBox.SelectedIndex = 5;
				break;
			case 30:
				TSB_TimeAccel.Text = "加速比：尽快";
				m_ConfigCode.TimeComboBox.SelectedIndex = 4;
				break;
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			HandleTimeCompressionChanged(bool_0: true);
			ProjectData.ClearProjectError();
		}
	}

