	private void RestartParams(object sender, EventArgs e)
	{
		AssetInterruptibleStruct().InitialDirectory = GameGeneral.ScenariosRootPath;
		AssetInterruptibleStruct().FileName = Client.CurrentScenario.Title + ".ini";
		if (AssetInterruptibleStruct().ShowDialog() != DialogResult.OK)
		{
			return;
		}
		bool bool_ = true;
		FileStream fileStream = File.Create(AssetInterruptibleStruct().FileName);
		using MemoryStream memoryStream = RCMS.recyclableMemoryStreamManager_0.GetStream();
		SBR.GenerateTemplate(Client.CurrentScenario, memoryStream, ref bool_);
		if (bool_)
		{
			fileStream.Write(memoryStream.ToArray(), 0, (int)memoryStream.Position);
			fileStream.Close();
			DarkMessageBox.ShowInformation("生成SBR模板文件！", "Success");
		}
		else
		{
			fileStream.Close();
			DarkMessageBox.ShowInformation("SBR template file not generated! See Exception Log", "Failed");
		}
	}

