	private void CancelParams(object sender, EventArgs e)
	{
		if (!Information.IsNothing(Client.HighlightedRefPoints) && Client.HighlightedRefPoints.Count >= 3)
		{
			List<ReferencePoint> list = new List<ReferencePoint>();
			List<UnguidedWeapon> list2 = new List<UnguidedWeapon>();
			foreach (UnguidedWeapon value in Client.CurrentScenario.UnguidedWeapons.Values)
			{
				list.AddRange(Client.HighlightedRefPoints);
				if (value.IsMine && value.GetIsInsideThisArea(list, Client.CurrentScenario, bool_0: false))
				{
					list2.Add(value);
				}
			}
			foreach (UnguidedWeapon item in list2)
			{
				Scenario scenario_ = Client.CurrentScenario;
				item.DestroyMe(ref scenario_, "Deleted mine");
			}
			Client.MustRefreshMainForm = true;
		}
		else
		{
			DarkMessageBox.ShowError("您必须首先选择至少3个参考点来定义雷区区域。", "没有选择足够的参考点！");
		}
	}

	private bool VerifyParams(float float_0, float float_1)
	{
		if (!(float_0 <= 0f) && float_1 > 0f)
		{
			if (float_0 < (float)WorldWindow1.Width)
			{
				if (float_1 < (float)WorldWindow1.Height)
				{
					return true;
				}
				return false;
			}
			return false;
		}
		return false;
	}

	private System.Drawing.Point[] ListParams(Geopoint_Struct geopoint_Struct_0, Sensor sensor_0, Module_Unit.Unit unit_0, float float_0, bool bool_0 = true)
	{
		System.Drawing.Point[] array = new System.Drawing.Point[0];
		List<RangeSymbol> list = PlatformComponent.RangeWedges_GetArcs(geopoint_Struct_0, sensor_0, float_0);
		if (sensor_0.VariableMaxRange)
		{
			foreach (RangeSymbol item in list)
			{
				System.Drawing.Point[] array_ = StartParams(geopoint_Struct_0, unit_0.CurrentHeading, sensor_0, item.LeftArc, item.RightArc, bool_0);
				array = Misc.CloneValue<System.Drawing.Point>(array, array_);
			}
			return array;
		}
		foreach (RangeSymbol item2 in list)
		{
			System.Drawing.Point[] array_2 = AssetParams(geopoint_Struct_0, unit_0.CurrentHeading, (float)item2.RangeNM, item2.LeftArc, item2.RightArc, bool_0);
			array = Misc.CloneValue<System.Drawing.Point>(array, array_2);
		}
		return array;
	}

	private bool ResolveParams(float float_0)
	{
		if (float_0 < 30f)
		{
			if (float_0 == 0f)
			{
				return false;
			}
			Geopoint_Struct geopoint_Struct = new Geopoint_Struct(GetMapCenter().Longitude, GetMapCenter().Latitude);
			Geopoint_Struct geopoint_Struct2 = default(Geopoint_Struct);
			Geodesic_EdWilliams.CalcPoint_Williams(geopoint_Struct.Longitude, geopoint_Struct.Latitude, ref geopoint_Struct2.Longitude, ref geopoint_Struct2.Latitude, float_0, 0);
			System.Drawing.Point point = ManagerListenerManager.SetInterruptibleMap(WorldWindow1, geopoint_Struct.Latitude, geopoint_Struct.Longitude);
			System.Drawing.Point point2 = ManagerListenerManager.SetInterruptibleMap(WorldWindow1, geopoint_Struct2.Latitude, geopoint_Struct2.Longitude);
			if (point.Y - point2.Y <= 2)
			{
				return false;
			}
			return true;
		}
		return true;
	}

	private System.Drawing.Point[] PostParams(Geopoint_Struct geopoint_Struct_0, float float_0, bool bool_0 = true)
	{
		System.Drawing.Point point = ManagerListenerManager.SetInterruptibleMap(WorldWindow1, geopoint_Struct_0.Latitude, geopoint_Struct_0.Longitude);
		Geopoint_Struct geopoint_Struct = default(Geopoint_Struct);
		try
		{
			Geodesic_EdWilliams.CalcPoint_Williams(geopoint_Struct_0.Longitude, geopoint_Struct_0.Latitude, ref geopoint_Struct.Longitude, ref geopoint_Struct.Latitude, float_0, 0);
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			Math2.CalcPoint_Vincenty(geopoint_Struct_0.Longitude, geopoint_Struct_0.Latitude, ref geopoint_Struct.Longitude, ref geopoint_Struct.Latitude, float_0, 0.0);
			ProjectData.ClearProjectError();
