	private void PublishParams(ref ActiveUnit activeUnit_0, Dictionary<int, Weapon> dictionary_0 = null)
	{
		if (Client.SelectedUnit == null || Client.CurrentSide.SelectedUnits.Count == 0)
		{
			return;
		}
		foreach (Module_Unit.Unit selectedUnit in Client.CurrentSide.SelectedUnits)
		{
			if (selectedUnit.IsMobileGroundUnit || selectedUnit.IsFacility || selectedUnit.IsBoat || selectedUnit.IsShip)
			{
				(ActiveUnit_DockingOps.ResultOfAttemptToScheduleUNREP, string) tuple = ((ActiveUnit)selectedUnit).DockingOps.IncludeDic(((ActiveUnit)selectedUnit).AI.LoginClient(), activeUnit_0, null, bool_0: false, 100, ActiveUnit_DockingOps.ResupplyRequest.Material, dictionary_0);
				if (tuple.Item1 != ActiveUnit_DockingOps.ResultOfAttemptToScheduleUNREP.Success && Operators.CompareString(tuple.Item2, string.Empty, TextCompare: true) != 0)
				{
					DarkMessageBox.ShowInformation(tuple.Item2, "无法补充弹药");
					Client.CurrentScenario.AddMessage("单元" + selectedUnit.Name + " 无法补充弹药。原因：" + tuple.Item2, "单元" + selectedUnit.Name + " 无法补充弹药", LoggedMessage.MessageType.DockingOps, 5, selectedUnit.ObjectID, Client.CurrentSide, new Geopoint_Struct(selectedUnit.GetLongitude(), selectedUnit.GetLatitude()));
				}
				((ActiveUnit)selectedUnit).AI.EvaluateUnitStatus(0f, bool_0: false, bool_1: false);
			}
		}
		Client.MustRefreshMainForm = true;
		RightColumn1.RefreshPanels(Client.CurrentScenario, Client.CurrentSide, Client.SelectedUnit, bool_0: false);
	}

