	public bool SaveAction()
	{
		if (Client.CurrentSide == null)
		{
			DarkMessageBox.ShowError("您必须至少创建一个分方才能保存想定。", "没有任何分方！");
			return false;
		}
		if (Client.CurrentGame.GameMode == Game._GameMode.ScenEdit)
		{
			AwakeGetter().Title = "保存想定";
		}
		else
		{
			AwakeGetter().Title = "保存推演";
		}
		base.Enabled = false;
		if (Client.CurrentScenario.FileName == null)
		{
			Client.CurrentUserAction = Client.UserAction.SavingScenario;
		}
		else
		{
			if (Operators.CompareString(Client.SaveScenarioPath, null, TextCompare: true) == 0)
			{
				AwakeGetter().InitialDirectory = GameGeneral.ScenariosRootPath;
				AwakeGetter().FileName = InterpreterObjectListener.TestInterruptibleTask(Client.CurrentScenario.Title);
			}
			else
			{
				AwakeGetter().InitialDirectory = Path.GetDirectoryName(Client.SaveScenarioPath);
				AwakeGetter().FileName = Client.SaveScenarioPath;
			}
			bool flag;
			if (flag = Client.CurrentGame.Status == Game._GameStatus.Running)
			{
				Client.CurrentGame.Pause();
			}
			AwakeGetter().AddExtension = true;
			if (Client.CurrentGame.GameMode == Game._GameMode.ScenEdit)
			{
				AwakeGetter().Filter = "想定文件|*.scen|存档文件|*.save|所有文件|*.*";
			}
			else
			{
				AwakeGetter().Filter = "存档文件|*.save|想定文件|*.scen|所有文件|*.*";
			}
			if (string.IsNullOrEmpty(AwakeGetter().InitialDirectory))
			{
				AwakeGetter().InitialDirectory = GameGeneral.ScenariosRootPath;
			}
			else if (!Path.GetFullPath(AwakeGetter().InitialDirectory).StartsWith(GameGeneral.ScenariosRootPath))
			{
				AwakeGetter().InitialDirectory = GameGeneral.ScenariosRootPath;
			}
			switch (AwakeGetter().ShowDialog())
			{
			case DialogResult.OK:
				Client.SaveCurrentScenario(bool_0: false);
				base.Enabled = true;
				Client.SaveScenarioPath = AwakeGetter().FileName;
				Client.AddFileNameToRecentList(Client.SaveScenarioPath);
				break;
			case DialogResult.Cancel:
				base.Enabled = true;
				break;
			case DialogResult.Abort:
				base.Enabled = true;
				break;
			case DialogResult.No:
				base.Enabled = true;
				break;
			}
			Client.CurrentUserAction = Client.UserAction.None;
			if (flag)
			{
				Client.CurrentGame.Run();
			}
		}
		return true;
	}

	private void UpdateInfo(object sender, EventArgs e)
	{
		if (Client.CurrentScenario.IsRunningInCampaignMode)
		{
			List<string> list = new List<string>();
			Campaign.GetCampaignsInFolder(GameGeneral.ScenariosRootPath, list);
			foreach (string item in list)
			{
				if (Operators.CompareString(Campaign.ReadFromFile(item).ID, Client.CurrentScenario.CampaignID, TextCompare: true) == 0)
				{
					Client.SaveScenarioPath = Path.Combine(Path.GetDirectoryName(item), Guid.NewGuid().ToString() + ".save");
					break;
				}
			}
		}
		if (Operators.CompareString(Client.SaveScenarioPath, null, TextCompare: true) == 0)
		{
			ComputeAuthentication(RuntimeHelpers.GetObjectValue(sender), e);
			return;
		}
		bool num = Client.CurrentGame.Status == Game._GameStatus.Running;
		if (num)
		{
			Client.CurrentGame.Pause();
		}
		base.Enabled = false;
		Client.SaveCurrentScenario(bool_0: false, Client.SaveScenarioPath);
		Client.AddFileNameToRecentList(Client.SaveScenarioPath);
		base.Enabled = true;
		Client.CurrentUserAction = Client.UserAction.None;
		if (num)
		{
			Client.CurrentGame.Run();
		}
	}

