	private void VerifyInfo()
	{
		List<Module_Unit.Unit> list = new List<Module_Unit.Unit>();
		Module_Unit.Unit unit_ = null;
		Geopoint_Struct geopoint_Struct_ = ManagerListenerManager.CalculateInterruptibleMap(WorldWindow1, CurrentMousePosition.X, CurrentMousePosition.Y);
		if (double.IsNaN(geopoint_Struct_.Latitude) || double.IsNaN(geopoint_Struct_.Longitude))
		{
			return;
		}
		short num = (short)(CurrentMousePosition.Y - 9);
		short num2 = (short)(CurrentMousePosition.Y + 9);
		short num3 = (short)(CurrentMousePosition.X - 9);
		short num4 = (short)(CurrentMousePosition.X + 9);
		int num5 = Client.MapSelectableUnits.Count - 1;
		for (int i = 0; i <= num5; i++)
		{
			Module_Unit.Unit unit = Client.MapSelectableUnits[i];
			Tuple<int, int> value = null;
			Client.MapVisibleUnit_ScreenCoords.TryGetValue(unit, out value);
			System.Drawing.Point point;
			if (Information.IsNothing(value))
			{
				point = ManagerListenerManager.SetInterruptibleMap(WorldWindow1, unit.GetLatitude(), unit.GetLongitude());
			}
			else
			{
				int item = value.Item1;
				int item2 = value.Item2;
				point = new System.Drawing.Point(item, item2);
			}
			if ((unit.IsActiveUnit && !((ActiveUnit)unit).CommStuff.IsConnectedToSideNetwork && !Client.CurrentMapProfile.GodsEye && !InterpreterObjectListener.CollectInterruptibleTask((ActiveUnit)unit)) || Client.CurrentSide.AwarenessLevel == Side.AwarenessLevel_Enum.Omniscient)
			{
				point = ManagerListenerManager.SetInterruptibleMap(WorldWindow1, ((ActiveUnit)unit).Latitude_LastReported.Value, ((ActiveUnit)unit).Longitude_LastReported.Value);
			}
			if (num >= point.Y || point.Y >= num2 || num3 >= point.X || point.X >= num4)
			{
				continue;
			}
			switch (Client.CurrentMapProfile.ViewMode)
			{
			case MapProfile.MapViewMode.UnitView:
				list.Add(unit);
				break;
			case MapProfile.MapViewMode.GroupView:
				if (!unit.IsActiveUnit || !((ActiveUnit)unit).IsGroupMember())
				{
					list.Add(unit);
				}
				break;
			}
		}
		switch (list.Count)
		{
		default:
		{
			float num6 = float.PositiveInfinity;
			foreach (Module_Unit.Unit item3 in list)
			{
				float num7 = (float)Module_Unit.RangeToPoint_Horiz_Angular(item3, geopoint_Struct_);
				if (num7 < num6)
				{
					num6 = num7;
					unit_ = item3;
				}
			}
			break;
		}
		case 1:
			unit_ = list[0];
			break;
		case 0:
			unit_ = null;
			break;
		}
		Client.SetConfiguration();
		Client.FillConfiguration(unit_);
	}

