			}
			List<ReferencePoint> list = new List<ReferencePoint>();
			list.AddRange(enumerable);
			NoNavZone noNavZone = new NoNavZone("区" + Conversions.ToString(Client.CurrentSide.NoNavZones.Count + 1), list, Client.CurrentScenario, Client.CurrentSide);
			Client.CurrentSide.NoNavZones.Add(noNavZone);
