	private void DeleteMapper(object sender, EventArgs e)
	{
		if (Information.IsNothing(Client.CurrentSide))
		{
			DarkMessageBox.ShowError("您必须至少创建一个分方才能打包想定。", "没有任何分方！");
			return;
		}
		AwakeGetter().Title = "分发想定包";
		base.Enabled = false;
		if (Information.IsNothing(Client.CurrentScenario.FileName))
		{
			Client.CurrentUserAction = Client.UserAction.PackingScenarioForDistribution;
			return;
		}
		AwakeGetter().InitialDirectory = GameGeneral.ScenariosRootPath;
		AwakeGetter().FileName = InterpreterObjectListener.TestInterruptibleTask(Client.CurrentScenario.FileName);
		bool flag;
		if (flag = Client.CurrentGame.Status == Game._GameStatus.Running)
		{
			Client.CurrentGame.Pause();
		}
		AwakeGetter().AddExtension = true;
		AwakeGetter().Filter = "打包想定文件（* .zip）| * .zip";
		if (string.IsNullOrEmpty(AwakeGetter().InitialDirectory))
		{
			AwakeGetter().InitialDirectory = GameGeneral.ScenariosRootPath;
		}
		else if (!Path.GetFullPath(AwakeGetter().InitialDirectory).StartsWith(GameGeneral.ScenariosRootPath))
		{
			AwakeGetter().InitialDirectory = GameGeneral.ScenariosRootPath;
		}
		switch (AwakeGetter().ShowDialog())
		{
		case DialogResult.OK:
			AttachmentRepoManager.PackageScenarioForDistribution(Client.CurrentScenario, Client.CurrentSide, AwakeGetter().FileName);
			base.Enabled = true;
			Client.SaveScenarioPath = AwakeGetter().FileName;
			break;
		case DialogResult.Cancel:
			base.Enabled = true;
			break;
		case DialogResult.Abort:
			base.Enabled = true;
			break;
		case DialogResult.No:
			base.Enabled = true;
			break;
		}
		Client.CurrentUserAction = Client.UserAction.None;
		if (flag)
		{
			Client.CurrentGame.Run();
		}
	}

