	private void ReadMapper(object sender, EventArgs e)
	{
		if (!Information.IsNothing(Client.CurrentScenario) && !Information.IsNothing(Client.CurrentSide) && Client.CurrentSide.SelectedUnits.Count <= 1 && Client.CurrentGame.Status == Game._GameStatus.Running && (RightColumn1.UpdateData || (!Information.IsNothing(Client.SelectedUnit) && (Client.SelectedUnit.IsWeapon || Client.SelectedUnit.DisableWriter()))))
		{
			RightColumn1.RefreshPanels(Client.CurrentScenario, Client.CurrentSide, Client.SelectedUnit, bool_0: false);
		}
		if (observerConnection <= 0f)
		{
			PeriodicHardGC();
		}
		else
		{
			observerConnection -= (float)((double)VisitInterruptibleCollection().Interval / 1000.0);
		}
	}

