	private void ListMapper(object sender, EventArgs e)
	{
		if (DarkMessageBox.ShowWarning("你确定吗？这将创建当前数据库的精简副本并将想定绑定到它！", "Confirm", DarkDialogButton.OkCancel) == DialogResult.OK)
		{
			if (string.IsNullOrEmpty(AwakeGetter().InitialDirectory))
			{
				AwakeGetter().InitialDirectory = GameGeneral.ScenariosRootPath;
			}
			else if (!Path.GetFullPath(AwakeGetter().InitialDirectory).StartsWith(GameGeneral.ScenariosRootPath))
			{
				AwakeGetter().InitialDirectory = GameGeneral.ScenariosRootPath;
			}
			if (AwakeGetter().ShowDialog() == DialogResult.OK)
			{
				string string_ = null;
				DB_Misc.BindScenToCustomDB(Client.CurrentScenario, ref string_);
				LoadSave.SaveScenario(Client.CurrentScenario, Client.CurrentSide, AwakeGetter().FileName, bool_0: false);
				DarkMessageBox.ShowInformation("完成！此想定的自定义数据库是：" + string_, "");
			}
		}
	}

