	private void RunMapper(object sender, EventArgs e)
	{
		if (Client.CurrentScenario.IsRunningInCampaignMode)
		{
			TSMI_SaveAs.Enabled = false;
		}
		else
		{
			TSMI_SaveAs.Enabled = true;
		}
		if (Client.CurrentScenario.ExecutionInProgress)
		{
			TSMI_NewScenario.Enabled = false;
			TSMI_LoadScenario.Enabled = false;
			TSMI_LoadRecent.Enabled = false;
			TSMI_NewScenario.ToolTipText = "Pause current scenario before starting new Scenario";
			TSMI_LoadScenario.ToolTipText = "Pause current scenario before starting new Scenario";
			TSMI_LoadRecent.ToolTipText = "Pause current scenario before starting new Scenario";
		}
		else
		{
			TSMI_NewScenario.Enabled = true;
			TSMI_LoadScenario.Enabled = true;
			TSMI_LoadRecent.Enabled = true;
			TSMI_NewScenario.ToolTipText = "";
			TSMI_LoadScenario.ToolTipText = "";
			TSMI_LoadRecent.ToolTipText = "";
		}
		if (GameGeneral.PE_MPOnly)
		{
			TSMI_NewScenario.Enabled = false;
			TSMI_LoadScenario.Enabled = false;
			TSMI_LoadRecent.Enabled = false;
			TSMI_SaveScen.Enabled = false;
			TSMI_SaveAs.Enabled = false;
			TSMI_Benchmark.Enabled = false;
		}
	}

