	{
		StringBuilder stringBuilder = new StringBuilder();
		bool flag = false;
		foreach (Module_Unit.Unit selectedUnit in Client.CurrentSide.SelectedUnits)
		{
			if (!Information.IsNothing(selectedUnit))
			{
				if (flag)
				{
					stringBuilder.Append(" , ");
				}
				stringBuilder.Append("{name='" + selectedUnit.Name.ToString() + "', guid='" + selectedUnit.ObjectID + "'}");
				flag = true;
			}
		}
		System.Windows.Forms.Clipboard.SetText(stringBuilder.ToString());
	}

