	public void ToggleIsolatedPOV()
	{
		if (!Client.CurrentScenario.DeclaredFeatures.Contains(Scenario.ScenarioFeatureOption.CommsDisruption))
		{
			return;
		}
		if (string.IsNullOrEmpty(Client.CurrentMapProfile.String_0))
		{
			if (Information.IsNothing(Client.SelectedUnit) || !Client.SelectedUnit.IsActiveUnit)
			{
				return;
			}
			Client.CurrentMapProfile.String_0 = Client.SelectedUnit.ObjectID;
		}
		else
		{
			Client.CurrentMapProfile.String_0 = null;
		}
		MessageLogControlViewModel.ResetLog();
		Client.MustRefreshMainForm = true;
	}

