	private void CustomizeManager(object sender, EventArgs e)
	{
		object processRequest = Client.m_ProcessRequest;
		ObjectFlowControl.CheckForSyncLockOnValueType(processRequest);
		bool lockTaken = false;
		try
		{
			Monitor.Enter(processRequest, ref lockTaken);
			Task.Factory.StartNew(delegate
			{
				SteamWorkshop.RunCallbacks();
			});
		}
		finally
		{
			if (lockTaken)
			{
				Monitor.Exit(processRequest);
			}
		}
	}

