	private void PopManager(object sender, EventArgs e)
	{
		if (!Client.CurrentScenario.IsEmpty() && DarkMessageBox.ShowWarning("你确定吗？当前想定中所有未保存的进度都将丢失。", "Confirm", DarkDialogButton.OkCancel) != DialogResult.OK)
		{
			return;
		}
		try
		{
			if (CountInterruptibleExpression().ShowDialog() == DialogResult.OK)
			{
				(DBRecord, DBOps.DBFileCheckResult) dBRecordByFilename = DBOps.GetDBRecordByFilename(CountInterruptibleExpression().FileName, bool_0: false);
				if (dBRecordByFilename.Item2 == DBOps.DBFileCheckResult.DBIsUnregistered)
				{
					DarkMessageBox.ShowWarning("The DB file you have selected is unregistered! Aborting...", string.Empty);
				}
				else if (dBRecordByFilename.Item2 == DBOps.DBFileCheckResult.DBFileNotPresent)
				{
					DarkMessageBox.ShowWarning("The DB file you have requested cannot be found! Aborting...", string.Empty);
				}
				else if (DBOps.QueryImporter(dBRecordByFilename.Item1))
				{
					DarkMessageBox.ShowWarning("The DB file you have selected has been tampered with! Aborting...", string.Empty);
				}
				else if (dBRecordByFilename.Item2 == DBOps.DBFileCheckResult.AllOK)
				{
					Client.IncludeConfiguration(dBRecordByFilename.Item1.Hash);
				}
				else
				{
					DarkMessageBox.ShowWarning("An unspecified error has occured! Aborting...", string.Empty);
				}
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			DarkMessageBox.ShowWarning("An unspecified error has occured! Aborting...", string.Empty);
			ProjectData.ClearProjectError();
		}
	}

