	private void InsertManager(object sender, EventArgs e)
	{
		if (DarkMessageBox.ShowWarning("你确定吗？", "移除此分方的所有目标", DarkDialogButton.OkCancel) != DialogResult.OK)
		{
			return;
		}
		new List<ActiveUnit>();
		foreach (Contact item in Client.CurrentSide.Contacts_List.ToList())
		{
			Side currentSide = Client.CurrentSide;
			Scenario scenario_ = Client.CurrentScenario;
			currentSide.DropContact(item, ref scenario_, bool_0: true);
			Side[] sides_ReadOnly = Client.CurrentScenario.Sides_ReadOnly;
			Side[] array = sides_ReadOnly;
			foreach (Side side in array)
			{
				if (side.GetConsidersThisSideToBe(Client.CurrentSide) == Misc.PostureStance.Friendly && side != Client.CurrentSide && side.Contacts_List.Contains(item))
				{
					scenario_ = Client.CurrentScenario;
					side.DropContact(item, ref scenario_, bool_0: false);
				}
			}
			Side currentSide2 = Client.CurrentSide;
			scenario_ = Client.CurrentScenario;
			currentSide2.DropBaseContact(item, ref scenario_);
		}
		Client.CurrentSide.ProcessContactListChanges(Client.CurrentScenario);
		Client.CurrentSide.ProcessBaseContactListChanges(Client.CurrentScenario);
		Client.MustRefreshMainForm = true;
	}

