	private void VerifyManager(object sender, EventArgs e)
	{
		Client.CurrentGame.Pause();
		PrintProc().InitialDirectory = GameGeneral.ScenariosRootPath;
		PrintProc().Multiselect = true;
		if (PrintProc().ShowDialog() != DialogResult.OK)
		{
			return;
		}
		List<string> list = new List<string>();
		List<string> list2 = new List<string>();
		string[] fileNames = PrintProc().FileNames;
		string[] array = fileNames;
		foreach (string text in array)
		{
			try
			{
				string string_ = string.Empty;
				Scenario scenario = Scenario.smethod_0(text, ref string_, null);
				string text2 = Path.GetDirectoryName(text) + "\\" + Path.GetFileName(text);
				if (!text2.EndsWith(".scen"))
				{
					text2 += ".scen";
				}
				int num = 0;
				while (FileExistsNative.FileExistsFast(text2))
				{
					text2 = text2.Replace(".scen", "");
					num++;
					text2 = text2 + Conversions.ToString(num) + ".scen";
					if (num > 999)
					{
						break;
					}
				}
				LoadSave.SaveScenario(scenario, scenario.GetCurrentSide(), text2, bool_0: false);
				list.Add(text);
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				list2.Add(text);
				Interaction.MsgBox("Failed to convert file: " + text + " to scenario. Error message: " + ex2.Message);
				ProjectData.ClearProjectError();
			}
		}
		string text3 = string.Empty;
		if (list.Count > 0)
		{
			text3 += "The following XML files were converted to scenarios successfully: ";
			foreach (string item in list)
			{
				text3 = text3 + "\r\n" + item;
			}
			text3 += "\r\n";
		}
		if (list2.Count > 0)
		{
			text3 += "The following XML files were NOT converted to scenarios due to errors: ";
			foreach (string item2 in list2)
			{
				text3 = text3 + "\r\n" + item2;
			}
			text3 += "\r\n";
		}
		Interaction.MsgBox(text3);
	}

