	protected override bool ProcessCmdKey(ref Message m, Keys keyData)
	{
		switch (keyData)
		{
		case Keys.Space:
			switch (Client.CurrentGame.Status)
			{
			case Game._GameStatus.Running:
				Client.CurrentGame.Pause();
				break;
			case Game._GameStatus.Paused:
				Client.CurrentGame.Run();
				break;
			}
			return true;
		case Keys.S | Keys.Control:
		{
			if (Operators.CompareString(Client.SaveScenarioPath, null, TextCompare: true) == 0)
			{
				SaveAction();
				return true;
			}
			base.Enabled = false;
			bool num = Client.CurrentGame.Status == Game._GameStatus.Running;
			if (num)
			{
				Client.CurrentGame.Pause();
			}
			Client.SaveCurrentScenario(bool_0: false, Client.SaveScenarioPath);
			if (num)
			{
				Client.CurrentGame.Run();
			}
			base.Enabled = true;
			return true;
		}
		case Keys.Subtract:
		case Keys.OemMinus:
		case Keys.Z | Keys.Shift | Keys.Control:
			Client.CurrentScenario.TimeCompression_Decrease();
			break;
		case Keys.Add:
		case Keys.Oemplus:
		case Keys.X | Keys.Shift | Keys.Control:
			Client.CurrentScenario.TimeCompression_Increase();
			break;
		}
		return false;
	}

