	private void PrintManager(object sender, EventArgs e)
	{
		try
		{
			if (CountInterruptibleExpression().ShowDialog() == DialogResult.OK)
			{
				(DBRecord, DBOps.DBFileCheckResult) dBRecordByFilename = DBOps.GetDBRecordByFilename(CountInterruptibleExpression().FileName, bool_0: true);
				if (dBRecordByFilename.Item2 == DBOps.DBFileCheckResult.DBFileNotPresent)
				{
					DarkMessageBox.ShowWarning("The DB file you have requested cannot be found! Aborting...", string.Empty);
				}
				else if (DBOps.QueryImporter(dBRecordByFilename.Item1))
				{
					DarkMessageBox.ShowWarning("The registered DB file you have selected has been tampered with! Aborting...", string.Empty);
				}
				else if (dBRecordByFilename.Item2 == DBOps.DBFileCheckResult.AllOK)
				{
					ItemExporter.ConnectInterruptibleTemplate.Migration.TargetDB = dBRecordByFilename.Item1;
					ItemExporter.ConnectInterruptibleTemplate.Migration.Show();
				}
				else
				{
					DarkMessageBox.ShowWarning("An unspecified error has occured! Aborting...", string.Empty);
				}
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			DarkMessageBox.ShowWarning("An unspecified error has occured! Aborting...", string.Empty);
			ProjectData.ClearProjectError();
		}
	}

