	public void HandleAllIndicators()
	{
		attrConnection += 30 - m_ExceptionConnection.ElapsedMilliseconds;
		m_ExceptionConnection.Restart();
		if (attrConnection < -600)
		{
			attrConnection = 0L;
		}
		else if (attrConnection < 30)
		{
			if (attrConnection <= 600)
			{
				int int_ = (int)Math.Round((double)(-attrConnection) / 30.0);
				{
					foreach (KeyValuePair<Control, Dictionary<VisualIndicator, Label>> registeredIndicator in RegisteredIndicators)
					{
						foreach (KeyValuePair<VisualIndicator, Label> item in registeredIndicator.Value)
						{
							PaintIndicator(item.Key, int_, registeredIndicator.Key);
							attrConnection = 0L;
						}
					}
					return;
				}
			}
			attrConnection = 0L;
		}
		else
		{
			attrConnection -= 30L;
		}
	}

	public void PaintIndicator(VisualIndicator visualIndicator_0, int int_0, Control control_0)
	{
		Label label = RegisteredIndicators[control_0][visualIndicator_0];
		if (visualIndicator_0.CallReponse())
		{
			System.Drawing.Point location = visualIndicator_0.LogoutReponse();
			System.Drawing.Size size = visualIndicator_0.SelectReponse();
			if (Operators.CompareString(visualIndicator_0.AnchorType, "UnitTracking", TextCompare: true) == 0)
			{
				if (visualIndicator_0.TargetUnit == null)
				{
					Notification.RemoveIndicator(visualIndicator_0);
					return;
				}
				Tuple<int, int> value = null;
				Client.MapVisibleUnit_ScreenCoords.TryGetValue(visualIndicator_0.TargetUnit, out value);
				if (Information.IsNothing(value))
				{
					location = ManagerListenerManager.SetInterruptibleMap(WorldWindow1, visualIndicator_0.TargetUnit.GetLatitude(), visualIndicator_0.TargetUnit.GetLongitude());
				}
				else
				{
					int item = value.Item1;
					int item2 = value.Item2;
					location = new System.Drawing.Point(item, item2);
				}
				location.X += -15;
				location.Y += -15;
				size = new System.Drawing.Size(30, 30);
			}
			GraphicsPath graphicsPath = new GraphicsPath();
			if (visualIndicator_0.DesignShape != 0 && visualIndicator_0.DesignShape != VisualIndicatorDesign.StaticCircle)
			{
				if (visualIndicator_0.DesignShape == VisualIndicatorDesign.EnclosingBox)
				{
					label.Location = location;
					graphicsPath.AddRectangle(new Rectangle(2, 2, size.Width, size.Height));
					graphicsPath.AddRectangle(new Rectangle(5, 5, size.Width, size.Height));
				}
			}
			else
			{
				int num = 80;
				label.Location = new System.Drawing.Point(location.X - 80, location.Y - 80);
				if (visualIndicator_0.DesignShape == VisualIndicatorDesign.AnimatedCircle)
				{
					if (visualIndicator_0.Animation_IsShrinkink)
					{
						visualIndicator_0.Animation_CurrentStep -= 1 + int_0;
					}
					else
					{
						visualIndicator_0.Animation_CurrentStep += 1 + int_0;
					}
					if (visualIndicator_0.Animation_CurrentStep > 15)
					{
						visualIndicator_0.Animation_IsShrinkink = true;
					}
					if (visualIndicator_0.Animation_CurrentStep <= 0)
					{
						visualIndicator_0.Animation_IsShrinkink = false;
					}
				}
				else if (visualIndicator_0.DesignShape == VisualIndicatorDesign.StaticCircle)
				{
					visualIndicator_0.Animation_CurrentStep = 0;
				}
				int num2 = (int)Math.Round((double)size.Width / 2.0);
				int num3 = num2 + visualIndicator_0.Animation_CurrentStep;
				int num4 = num2 + visualIndicator_0.Animation_CurrentStep + 2;
				graphicsPath.AddEllipse(new Rectangle((int)Math.Round((double)size.Width / 2.0 + 0.0 + (double)num - (double)num4), (int)Math.Round((double)size.Height / 2.0 + (double)num + 0.0 - (double)num4), num4 * 2, num4 * 2));
				graphicsPath.AddEllipse(new Rectangle((int)Math.Round((double)size.Width / 2.0 + 2.0 + (double)num - (double)num4), (int)Math.Round((double)size.Height / 2.0 + (double)num + 2.0 - (double)num4), num3 * 2, num3 * 2));
				size.Width = 600;
				size.Height = 600;
			}
			label.BackColor = visualIndicator_0.DrawColor;
			label.Size = new System.Drawing.Size(size.Width + 5, size.Height + 5);
			label.Region = new Region(graphicsPath);
			label.Visible = true;
			label.BringToFront();
		}
		else
		{
			label.Visible = false;
		}
	}

