	private void LogoutGetter(object sender, EventArgs e)
	{
		List<ReferencePoint> list = new List<ReferencePoint>();
		foreach (ReferencePoint refPoint in Client.CurrentSide.RefPoints)
		{
			if (refPoint.IsHighlighted)
			{
				list.Add(refPoint);
			}
		}
		if (list.Count < 3)
		{
			DarkMessageBox.ShowError("There are less than the minimum 3 highlighted reference points (" + list.Count + ") which are required to create a valid zone ", "Error while creating a zone");
		}
		else if ((Zone.ValidateArea(list) || DarkMessageBox.ShowError("The set of reference points doesn't create a valid shape, this may be due to the ordering of these reference points. Do you want to create this invalid zone [Ok] and correct this later or [Cancel] the creation ?", "Error while creating a zone", DarkDialogButton.OkCancel) != DialogResult.Cancel) && !Information.IsNothing(Client.CurrentSide))
		{
			Zone zone = new Zone(InputDialog.CallDialog("区域名称", "输入区域名称...", "新建区域"), list);
			Client.CurrentSide.StandardZones.Add(zone);
			zone.AreaColor = System.Drawing.Color.FromArgb(60, 100, 100, 100);
		}
	}

